import React, { useState, useMemo, useRef, useEffect, useCallback } from "react";
import { Printer, FileDown, FileCode2, Users, ChevronDown, ChevronRight, FileText, Layers, Upload, Download, Plus, Trash2, Check, Calendar as CalendarIcon, PanelLeft as PanelIcon } from "lucide-react";

/* ==================================================================
   Letter of engagement.

   LIBRARY holds every clause. Nothing in the renderer knows about
   accountancy. The Templates tab edits the library, exports it as
   JSON and imports it back, so wording changes never touch code.
   In production this JSON is the seed for the clause tables.
   ================================================================== */

const SEED_LIBRARY = {"terms": [{"n": 1, "title": "Applicable Law", "paras": [{"k": "p", "t": "This engagement letter shall be governed by, and construed in accordance with English law. The Courts of England shall have exclusive jurisdiction in relation to any claim, dispute or difference concerning the engagement letter (including the firm's terms of business) and any matter arising from it. Each party irrevocably waives any right it may have to object to an action being brought in those Courts, to claim that the action has been brought in an inconvenient forum, or to claim that those Courts do not have jurisdiction."}, {"k": "p", "t": "Persons who are not party to this agreement shall have no rights under the Contracts (Rights of Third Parties) Act 1999 to enforce any term of this agreement. This clause does not affect any right or remedy of any person which exists or is available otherwise than pursuant to that Act."}, {"k": "p", "t": "The advice we give you is for your sole use and is confidential to you and will not constitute advice for any third party to whom you may communicate it. We will accept no responsibility to third parties for any aspect of our professional services or work that is made available to them."}], "dpOnly": false}, {"n": 2, "title": "Client Identification", "paras": [{"k": "p", "t": "As with other professional firms, we are required to identify our clients for the purposes of the UK anti-money laundering legislation. We may request from You, and retain, such information and documentation as we require for these purposes and/or make searches of appropriate databases. If we are not able to obtain satisfactory evidence of Your identity, we will not be able to proceed with the engagement."}], "dpOnly": false}, {"n": 3, "title": "Quality of Service", "paras": [{"k": "p", "t": "We aim to provide you with a fully satisfactory service and {{epTitle}} {{engagementPartner}} as engagement partner will seek to ensure that this is so. If, however, you are unable to deal with any difficulty through {{epObj}} and {{epPoss}} team please contact {{esTitle}} {{escalationPartner}}, telephone number 024 7662 7200. We undertake to look into any complaint carefully and promptly and to do all we can to explain the position to you. If we do not answer your complaint to your satisfaction you may of course take up the matter with the Institute of Chartered Accountants in England and Wales (ICAEW) by whom we are regulated."}], "dpOnly": false}, {"n": 4, "title": "Client Monies", "paras": [{"k": "p", "t": "We may, from time to time, hold money on your behalf. Such money will be held in trust in a client bank account, which is segregated from the firm's funds. The account will be operated, and all funds dealt with, in accordance with the Clients' Money Regulations of the ICAEW."}, {"k": "p", "t": "In order to avoid an excessive amount of administration, interest will only be paid to you where the amount of interest that would be earned on the balances held on your behalf in any calendar year exceeds £25. Any such interest would be calculated using the prevailing rate applied by Lloyds Bank Plc for small deposits subject to the minimum period of notice for withdrawals. Subject to any tax legislation, interest will be paid gross."}, {"k": "p", "t": "If the total sum of money held on your behalf exceeds £10,000 for a period of more than 30 days, or such sum is likely to be held for more than 30 days, then the money will be placed in a separate interest-bearing client bank account designated to you. All interest earned on such money will be paid to you. Subject to any tax legislation, interest will be paid gross."}, {"k": "p", "t": "We will return monies held on your behalf promptly as soon as there is no longer any reason to retain those funds. If any funds remain in our clients account that are unclaimed and the client to which they relate has remained untraced for five years or we as a firm cease to practise then we may pay those monies to a registered charity."}], "dpOnly": false}, {"n": 5, "title": "Investment Advice", "paras": [{"k": "p", "t": "Although we are not authorised by the Financial Conduct Authority to conduct Investment Business, we are licensed by the ICAEW to provide certain limited investment services where these are complementary to, or arise out of, the professional services we are providing to you."}, {"k": "p", "t": "Such assistance may include the following:"}, {"k": "bullet", "t": "advising you on investments generally, but not recommending a particular investment or type of investment;"}, {"k": "bullet", "t": "referring you to a Permitted Third Party (PTP) (an independent firm authorised by the FCA) and assisting you and the authorised third party during the course of any advice given by that party. This may include comment on, or explanation of, the advice received (but we will not make alternative recommendations). The PTP will issue you with his own terms and conditions letter, will be remunerated separately for his services and will take full responsibility for compliance with the requirements of the Financial Services and Markets Act 2000. The firm may receive commission from such an introduction, in which case you will be fully informed of the expected size and nature of such commission at the time of the introduction."}, {"k": "bullet", "t": "advising on the sale of a contractually based investment other than disposing of any rights or interests which you may have as a member of a personal pension scheme;"}, {"k": "bullet", "t": "advising and assisting you in transactions concerning shares or other securities not quoted on a recognised exchange;"}, {"k": "bullet", "t": "managing investments or acting as trustee (or donee of a power of attorney) where decisions to invest are taken on the advice of an authorised person."}, {"k": "p", "t": "We may also, on the understanding that the shares or other securities of the company are not publicly traded:"}, {"k": "bullet", "t": "advise the company, existing or prospective shareholders in relation to exercising rights, taking benefits or share options valuation and methods;"}, {"k": "bullet", "t": "arrange any agreements in connection with the issue, sale or transfer of the company's shares or other securities;"}, {"k": "bullet", "t": "arrange for the issue of the new shares; and"}, {"k": "bullet", "t": "act as the addressee to receive confirmation of acceptance of offer documents etc."}], "dpOnly": false}, {"n": 6, "title": "Commission and Other Benefits", "paras": [{"k": "p", "t": "In some circumstances we may receive commissions or other benefits for introductions to other professionals or in respect of transactions which we arrange for you."}, {"k": "bullet", "t": "If this happens, we will notify you in writing within 30 days of our receipt of the commission of the amount and terms of payment and receipt of any such commissions or benefits. The fees you would otherwise pay will not be reduced by the amount of the commissions or benefits. You agree that we can retain the commission or other benefits without being liable to account to you for any such amounts."}, {"k": "bullet", "t": "The following are examples of likely commissions that may be received by us and the likely amounts. These are examples only and may not cover all receipts in the future.", "gapAfter": 0}, {"k": "table", "cells": ["Provided service", "Name or type of firm paying commission", "Basis of commission", "Rate of commission", "Frequency"], "head": true}, {"k": "table", "cells": ["Accounting software", "Sage", "Variable", "20% of monthly subscription", "Monthly for life of contract"]}, {"k": "table", "cells": ["Invoice discounting or loan facilities", "Banks", "Fixed", "1% of loan value", "One off"]}, {"k": "bullet", "t": "If in the future, abnormally large commissions (for example more than double the largest amount shown above) are received which were not envisaged when the engagement letter was signed, we will obtain specific consent to the retention of those commissions."}], "dpOnly": false}, {"n": 7, "title": "Fees", "paras": [{"k": "p", "t": "Our fees may depend not only on the time spent on your affairs by the partners and our staff and on the levels of skill and responsibility involved, but also the level of risk identified and any advice provided. Unless otherwise agreed, our fees will be billed at appropriate intervals during the course of the year and will be due 30 days after presentation."}, {"k": "cont", "t": "Our standard charge rates excluding VAT are:-", "gapAfter": 0}, {"k": "table", "cells": ["", "Hourly Rate"], "head": true}, {"k": "table", "cells": ["Director", "£315"]}, {"k": "table", "cells": ["Tax Director", "£375"]}, {"k": "table", "cells": ["Associate & Tax Manager", "£175 to £185"]}, {"k": "table", "cells": ["Manager", "£125 to £140"]}, {"k": "table", "cells": ["Senior", "£80 to £90"]}, {"k": "table", "cells": ["Trainee", "£55 to £70"]}, {"k": "p", "t": "We may indicate a fixed/indicative fee for the provision of specific services. We will not usually identify fixed fees for more than a year in advance as these may need to be revised in the light of subsequent events. Where we estimate our fees for any specific work, this will not be binding unless this is clearly stated to you."}, {"k": "p", "t": "If it is necessary to carry out work outside the responsibilities outlined in this letter it will involve additional fees. Accordingly we would like to point out that it is in your interests to ensure that your records etc are completed to the agreed stage."}, {"k": "cont", "t": "Unless otherwise agreed to the contrary our fees do not include the costs of any third party, counsel or other professional fees. If these costs are incurred to fulfil our engagement, such necessary additional charges may be payable by you."}, {"k": "cont", "t": "Our fees will exclude out of pocket expenses. Out of pocket expenses (plus VAT (if applicable)) will be billed as incurred for reimbursement by you."}, {"k": "p", "t": "Invoices are payable in full before the report is signed and the accounts are made available for filing."}, {"k": "p", "t": "In some cases, You may be entitled to assistance with Your professional fees, particularly in relation to any investigation into Your tax affairs by HMRC. Assistance may be provided through insurance policies You hold via membership of a professional or trade body. Other than where such an investigation policy was arranged through us You will need to advise us of any such cover that You have. You will remain liable for our fees regardless of whether all or part are liable to be paid by Your insurers."}, {"k": "p", "t": "It is our normal practice to request that clients make arrangements to pay a proportion of their fee on a monthly standing order. These standing orders will be applied to fees arising from work agreed in this letter of engagement for the current and ensuing years. Once we have been able to assess the amount of work and time involved we would be grateful if you would agree to pay an amount to us on a regular basis."}, {"k": "p", "t": "Our terms relating to payment of amounts invoiced and not covered by standing orders, where appropriate, are strictly 30 days net. Interest will be charged on all overdue debts at the rate stated on the invoice, or at the rate for the time being applicable under the Late Payment of Commercial Debts (Interest) Act 1998, whichever is the higher. We reserve the right to charge You any costs and disbursements (including third party legal fees) we incur in recovering outstanding fees from You. We also reserve the right to suspend our services or to cease to act for You on giving written notice if payment of any fees is unduly delayed. We intend to exercise these rights only where it is fair and reasonable to do so."}, {"k": "p", "t": "Should You fail to satisfy Your obligations under the terms of this agreement relating to payment, You agree to jointly and severally personally guarantee to pay all sums to us that are outstanding including any other costs of recovery immediately on demand under the terms of this agreement."}, {"k": "p", "t": "If You do not accept that a Request for Payment of a fee is fair and reasonable You must notify us within 21 days of receipt, failing which, You will be deemed to have accepted that payment is due."}], "dpOnly": false}, {"n": 8, "title": "Retention of and Access to Records", "paras": [{"k": "p", "t": "During the course of our work we will collect information from you and others acting on your behalf and will return any original documents to you following the preparation of your financial statements and returns."}, {"k": "cont", "t": "Documents and records relevant to Your tax affairs are required by law to be retained as follows:-", "gapAfter": 1}, {"k": "cont", "t": "Individuals, Trustees and Partnerships:", "gapAfter": 0}, {"k": "bullet", "t": "with trading of rental income: five years and ten months after the end of the tax year;"}, {"k": "bullet", "t": "otherwise: 22 months after the end of tax year;"}, {"k": "cont", "t": "Companies, LLPs and other corporate entities:", "gapAfter": 0}, {"k": "bullet", "t": "six years from the end of the accounting period."}, {"k": "p", "t": "Whilst certain documents may legally belong to you, we intend to destroy correspondence and other papers that we store which are more than seven years old, other than documents which we consider to be of continuous significance. If you require retention of any document you must notify us of that fact in writing."}], "dpOnly": false}, {"n": 9, "title": "Lien", "paras": [{"k": "p", "t": "Insofar as we are permitted to do so by law or professional guidelines, we reserve the right to exercise a lien over all funds, documents and records in our possession relating to all engagements for You until all outstanding fees and disbursements are paid in full."}], "dpOnly": false}, {"n": 10, "title": "Proceeds of Crime Act 2002 and Money Laundering Regulations 2007", "paras": [{"k": "p", "t": "In common with all accountancy and legal practices, we are required by the Proceeds of Crime Act 2002 and the Money Laundering Regulations 2007 to:-"}, {"k": "bullet", "t": "have due diligence procedures for the identification of all clients;"}, {"k": "bullet", "t": "maintain appropriate records of evidence to support customer due diligence; and"}, {"k": "bullet", "t": "report in accordance with the relevant legislation and regulations."}], "dpOnly": false}, {"n": 11, "title": "Electronic Communication", "paras": [{"k": "p", "t": "Internet communications are capable of data corruption and therefore we do not accept any responsibility for changes made to such communications after their despatch. It may therefore be inappropriate to rely on advice contained in an e-mail without obtaining written confirmation of it. We do not accept responsibility for any errors or problems that may arise through the use of internet communication and all risks connected with sending commercially sensitive information relating to {{entityDescriptor}} are borne by you. If you do not agree to accept this risk, you should notify us in writing that e-mail is not an acceptable means of communication."}, {"k": "p", "t": "It is the responsibility of the recipient to carry out a virus check on any attachments received."}], "dpOnly": false}, {"n": 12, "title": "Data Protection", "paras": [{"k": "p", "t": "To enable us to discharge the services agreed in this engagement letter, comply with related legal and regulatory obligations and for other related purposes including updating and enhancing client records and analysis for management purposes, as a data controller, we may obtain, use, process and disclose personal data about {{entity}} as described in our privacy notice. We confirm when processing data on your behalf that we will comply with the provisions of all relevant data protection legislation and regulation."}, {"k": "p", "t": "You are also an independent controller responsible for complying with data protection legislation and regulation in respect of the personal data you process and, accordingly where you disclose personal data to us you confirm that such disclosure is fair and lawful and otherwise does not contravene relevant requirements. Nothing within this engagement letter relieves you as a data controller of your own direct responsibilities and liabilities under data protection legislation and regulation."}, {"k": "p", "t": "Our privacy notice, which can be found on our website at www.luckmans.com explains how we process personal data in respect of the various services that we provide."}, {"k": "h2", "t": "Acting as a Data Processor"}, {"k": "p3", "t": "In this clause:", "ind": 1260, "hangW": 720}, {"k": "cont", "t": "'client personal data' means any personal data provided to us by you, or on your behalf, for the purpose of providing our services to you, pursuant to our engagement letter with you;", "ind": 1260, "flat": true, "gapAfter": 1}, {"k": "cont", "t": "'data protection legislation' means all applicable privacy and data protection legislation and regulations including PECR, the GDPR and any applicable national laws, regulations and secondary legislation in the UK relating to the processing of personal data and the privacy of electronic communications, as amended, replaced or updated from time to time;", "ind": 1260, "flat": true, "gapAfter": 1}, {"k": "cont", "t": "'controller', 'data subject', 'personal data', 'personal data breach', 'processor', 'process' and 'supervisory authority' shall have the meanings given to them in the data protection legislation;", "ind": 1260, "flat": true, "gapAfter": 1}, {"k": "cont", "t": "'GDPR' means the General Data Protection Regulation ((EU) 2016/679); and 'PECR' means the Privacy and Electronic Communications (EC Directive) Regulations 2003 (SI 2426/2003).", "ind": 1260, "flat": true, "gapAfter": 1}, {"k": "p3", "t": "We shall both comply with all applicable requirements of the data protection legislation. This clause 12.4 is in addition to, and does not relieve, remove or replace, either of our obligations under the data protection legislation.", "ind": 1260, "hangW": 720}, {"k": "p3", "t": "We both acknowledge that for the purposes of the data protection legislation,", "ind": 1260, "hangW": 720}, {"k": "cont", "t": "you are the data controller and we are the data processor. Schedule A sets out the scope, nature and purpose of processing by us, the duration of the processing and the types of personal data and categories of data subject.", "ind": 1260, "flat": true, "gapAfter": 1}, {"k": "p3", "t": "In respect of the client personal data, unless otherwise required by applicable laws or other regulatory requirements, we shall:", "ind": 1260, "hangW": 720}, {"k": "bullet", "t": "process the client personal data only in accordance with your lawful written instructions, in order to provide you with the services pursuant to our engagement with you and in accordance with applicable data protection legislation;", "ind": 1710}, {"k": "bullet", "t": "disclose and transfer the client personal data to our regulatory bodies or other third parties (for example, our professional advisors or service providers) as and to the extent necessary in order to provide you with the services pursuant to our engagement with you in relation to those services;", "ind": 1710}, {"k": "bullet", "t": "disclose the client personal data to courts, government agencies and other third parties as and to the extent required by law;", "ind": 1710}, {"k": "bullet", "t": "maintain written records of our processing activities performed on your behalf which shall include: (i) the categories of processing activities performed; (ii) details of any on cross border data transfers outside of the European Economic Area (EEA); and (iii) a general description of security measures implemented in respect of the client personal data;", "ind": 1710}, {"k": "bullet", "t": "maintain commercially reasonable and appropriate security measures, including administrative, physical and technical safeguards, to protect against unauthorised or unlawful processing of any client personal data and against accidental loss or destruction of, or damage to, such client personal data.", "ind": 1710}, {"k": "bullet", "t": "return or delete all the client personal data upon the termination of the engagement with you pursuant to which we agreed to provide the services;", "ind": 1710}, {"k": "bullet", "t": "ensure that only those personnel who need to have access to the client personal data are granted access to it and that all of the personnel authorised to process the client personal data are bound by a duty of confidentiality;", "ind": 1710}, {"k": "bullet", "t": "notify you if we appoint a sub-processor (but only if you have given us your prior written consent, such consent not to be reasonably withheld or delayed) and ensure any agreement entered into with the relevant sub-processor includes similar terms as the terms set out in this clause 12.4. Our current list of appointed sub-processors is in schedule B;", "ind": 1710}, {"k": "bullet", "t": "where we transfer the client personal data to a country or territory outside the EEA to do so in accordance with data protection legislation;", "ind": 1710}, {"k": "bullet", "t": "notify you promptly if:", "ind": 1710, "gapAfter": 0}, {"k": "bullet2", "t": "we receive a request, complaint or any adverse correspondence from or on behalf of a relevant data subject, to exercise their data subject rights under the data protection legislation or in respect of the client personal data; or", "ind": 2160, "gapAfter": 0}, {"k": "bullet2", "t": "we are served with an information or assessment notice, or receive any other material communication in respect of our processing of the client personal data from a supervisory body (for example, the Information Commissioner's Officer);", "ind": 2160, "gapAfter": 0}, {"k": "bullet2", "t": "notify you, without undue delay, in the event that we reasonably believe that there has been a personal data breach in respect of the client personal data;", "ind": 2160, "gapAfter": 0}, {"k": "bullet2", "t": "at your cost and upon receipt of your prior written notice, allow you, on an annual basis and/or in the event that we notify you of personal data breach in respect of the client personal data, reasonable access to the relevant records, files, computer or other communication systems, for the purposes of reviewing our compliance with the data protection laws.", "ind": 2160, "gapAfter": 1}, {"k": "p3", "t": "Without prejudice to the generality of clause 12.4.2, you will ensure that you have all necessary appropriate consents and notices in place to enable the lawful transfer of the client personal data to us.", "ind": 1260, "hangW": 720}, {"k": "p3", "t": "Should you require any further details regarding our treatment of personal data, please contact our data protection manager Mark Spafford marks@luckmans.com", "ind": 1260, "hangW": 720}], "dpOnly": true, "parasNoDp": [{"k": "p", "t": "To enable us to discharge the services agreed in this engagement letter, comply with related legal and regulatory obligations and for other related purposes including updating and enhancing client records and analysis for management purposes, as a data controller, we may obtain, use, process and disclose personal data about {{entity}} as described in our privacy notice. We confirm when processing data on your behalf that we will comply with the provisions of all relevant data protection legislation and regulation."}, {"k": "p", "t": "You are also an independent controller responsible for complying with data protection legislation and regulation in respect of the personal data you process and, accordingly where you disclose personal data to us you confirm that such disclosure is fair and lawful and otherwise does not contravene relevant requirements. Nothing within this engagement letter relieves you as a data controller of your own direct responsibilities and liabilities under data protection legislation and regulation."}, {"k": "p", "t": "Our privacy notice, which can be found on our website at www.luckmans.com explains how we process personal data in respect of the various services that we provide."}]}, {"n": 13, "title": "Confidentiality", "paras": [{"k": "p", "t": "Where you give us confidential information, we confirm that we shall at all times keep it confidential, other than as required by law or as provided for in regulatory (including external peer reviews), ethical or other professional statements relevant to our engagement. This will apply during and after this engagement."}, {"k": "p", "t": "You agree that, if we act for other clients who are or who become Your competitors, to comply with our duty of confidentiality it will be sufficient for us to take such steps as we think appropriate to preserve the confidentiality of information given to us by You, both during and after this engagement. These may include taking the same or similar steps as we take in respect of the confidentiality of our own information."}, {"k": "p", "t": "In addition, if we act for other clients whose interests are or may be adverse to Yours, we will manage the conflict by implementing additional safeguards to preserve confidentiality. Safeguards may include measures such as separate teams, physical separation of teams, and separate arrangements for storage of, and access to, information."}, {"k": "p", "t": "You agree that the effective implementation of such steps or safeguards as described above will provide adequate measures to avoid any real risk of confidentiality being impaired."}, {"k": "p", "t": "We may, on occasions, subcontract work on Your affairs to other tax or accounting professionals. The subcontractors will be bound by our client confidentiality terms."}, {"k": "p", "t": "If we use external or cloud based systems, we will ensure confidentiality of Your information is maintained."}, {"k": "p", "t": "We reserve the right, for the purpose of promotional activity, training or for other business purposes, to mention that You are a client. As stated above, we will not disclose any confidential information."}, {"k": "p", "t": "We may subcontract our work to other professionals within the sector. Any subcontractors are also bound by our client confidentiality terms."}], "dpOnly": false}, {"n": 14, "title": "Disengagement", "paras": [{"k": "p", "t": "Should we resign or be requested to resign we will normally issue a disengagement letter to ensure that our respective responsibilities are clear."}, {"k": "p", "t": "If we are asked to stop working on the engagement, we reserve the right to charge a fee which relates to the time we have spent on the matter up to that date, but it will be limited and it will not exceed any fixed fee already agreed."}], "dpOnly": false}, {"n": 15, "title": "Period of Engagement and Termination", "paras": [{"k": "p", "t": "Unless otherwise agreed in the engagement covering letter our work will begin when we receive Your implicit or explicit acceptance of that letter. Except as stated in that letter we will not be responsible for periods before that date."}, {"k": "p", "t": "Each of us may terminate this agreement by giving not less than 21 days' notice in writing to the other party except where You fail to cooperate with us or we have reason to believe that You have provided us or HMRC with misleading information, in which case we may terminate this agreement immediately. Termination will be without prejudice to any rights that may have accrued to either of us prior to termination."}, {"k": "p", "t": "We reserve the right to terminate the engagement between us with immediate effect in the event of: Your insolvency, bankruptcy or other arrangement being reached with creditors; an independence issue or change in the law which means we can no longer act; failure to pay our fees by the due dates; or either party being in breach of their obligations if this is not corrected within 30 days of being asked to do so."}, {"k": "p", "t": "In the event of termination of this contract, we will endeavour to agree with You the arrangements for the completion of work in progress at that time, unless we are required for legal or regulatory reasons to cease work immediately. In that event, we shall not be required to carry out further work and shall not be responsible or liable for any consequences arising from termination."}], "dpOnly": false}, {"n": 16, "title": "Limitation of Liability", "paras": [{"k": "p", "t": "We will provide our services with reasonable care and skill. Our liability to You is limited to losses, damages, costs and expenses directly caused by our negligence or wilful default. We will not be liable for any losses, damages, costs or expenses on any area that we are not specifically asked to advise upon, and we have no liability or obligation whatsoever to proactively offer advice on any other planning, advice or other items, unless we agree to include them in our engagement."}], "dpOnly": false}, {"n": 99, "title": "Exclusion of Liability for Loss Caused by Others", "paras": [{"k": "p", "t": "We will not be liable if such losses, penalties surcharges, interest or additional tax liabilities are caused by the acts or omissions of any other person or due to the provision to us of incomplete, misleading or false information or if they are caused by failure to act on our advice or a failure to provide us with relevant information."}]}, {"n": 17, "title": "Exclusion of Liability in Relation to Circumstances Beyond our Control", "paras": [{"k": "p", "t": "We will not be liable to You for any delay or failure to perform our obligations under this engagement letter if the delay or failure is caused by circumstances outside of our reasonable control."}], "dpOnly": false}, {"n": 18, "title": "Exclusion of Liability Relating to the Discovery of Fraud Etc", "paras": [{"k": "p", "t": "We will not be responsible or liable for any loss, damage or expense incurred or sustained if information material to the service we are providing is withheld or concealed from us or misrepresented to us. This applies equally to fraudulent acts, misrepresentation or wilful default on the part of any party to the transaction and their directors, officers, employees, agents or advisers."}, {"k": "p", "t": "This exclusion shall not apply where such misrepresentation, withholding or concealment is or should (in carrying out the procedures which we have agreed to perform with reasonable care and skill) have been evident to us without further enquiry beyond that which it would have been reasonable for us to have carried out in the circumstances."}], "dpOnly": false}, {"n": 19, "title": "Indemnity for Unauthorised Disclosure", "paras": [{"k": "p", "t": "You agree to indemnify us and our agents in respect of any claim (including any claim for negligence) arising out of any unauthorised disclosure by You or by any person for whom You are responsible of our advice and opinions, whether in writing or otherwise. This indemnity will extend to the cost of defending any such claim, including payment at our usual rates for the time that we spend in defending it."}], "dpOnly": false}, {"n": 20, "title": "External Review", "paras": [{"k": "p", "t": "As part of our ongoing commitment to providing a quality service, our files are periodically reviewed by an independent regulatory or quality control body. These reviewers are highly experienced and professional people and, of course, are bound by the same rules for confidentiality as us."}], "dpOnly": false}, {"n": 21, "title": "Professional Rules and Practice Guidelines", "paras": [{"k": "p", "t": "We will observe and act in accordance with the bye-laws, regulations and Code of Ethics of the ICAEW and accept instructions to act for you on this basis. In particular you give us the authority to correct errors made by HMRC where we become aware of them. We will not be liable for any loss, damage or cost arising from our compliance with statutory or regulatory obligations. You can see copies of these requirements in our offices. The requirements are also available on the internet at www.icaew.com/regulations."}], "dpOnly": false}, {"n": 22, "title": "Conflicts of Interests", "paras": [{"k": "p", "t": "We reserve the right during our engagement with you to deliver services to other clients whose interests might compete with yours or are or may be adverse to yours. Subject to our confidentiality clause we confirm that we will notify you immediately should we become aware of any conflict of interest involving us and affecting {{entityShort}}."}, {"k": "p", "t": "If a conflict of interest should arise, either between two or more of our clients, or in the provision of multiple services to a single client, we will take such steps as are necessary to deal with the conflict. In resolving the conflict, we would be guided by our Code of Ethics Including the Data Protection Act 2018, the General Data Protection Regulation (GDPR) and any related regulations."}], "dpOnly": false}, {"n": 23, "title": "The Provision of Services Regulations 2009", "paras": [{"k": "p", "t": "We are registered to carry on audit work in the UK and Ireland by the ICAEW. Details of our audit registration can be viewed at www.auditregister.org.uk for the UK and Ireland at www.cro.ie/auditors under reference number C002512580."}, {"k": "p", "t": "Our professional indemnity insurer is QBE UK Limited, QBE European Operations, Plantation Place, 30 Fenchurch Street, London EC3M 3BD. The territorial coverage is worldwide excluding professional business carried out from an office in the United States of America or Canada and excludes any action for a claim brought in any court in the United States or Canada."}], "dpOnly": false}, {"n": 24, "title": "Timing of Our Services", "paras": [{"k": "p", "t": "If you provide us with all information and explanations on a timely basis in accordance with our requirements, we will plan to undertake the work within a reasonable period of time in order to meet any regulatory deadlines. However, failure to complete our services prior to any such regulatory deadline would not, of itself, mean that we are liable for any penalty or additional costs arising."}], "dpOnly": false}, {"n": 25, "title": "Intellectual Property Rights", "paras": [{"k": "p", "t": "We will retain all intellectual property rights in any document prepared by us during the course of carrying out the engagement except where the law specifically states otherwise."}, {"k": "p", "t": "You are not permitted to use our name in any statement or document You may issue unless our prior written consent has been obtained. The only exception to this restriction would be statements or documents that, in accordance with applicable law, are to be made public."}], "dpOnly": false}, {"n": 26, "title": "Interpretation", "paras": [{"k": "p", "t": "If any provision of this engagement letter or enclosed schedules is held to be void, then that provision will be deemed not to form part of this contract and the remainder of this agreement shall be interpreted as if such provision had never been inserted."}, {"k": "p", "t": "In the event of any conflict between these terms of business and the engagement letter or appendices, the relevant provision in the engagement letter or schedules will take precedence."}], "dpOnly": false}], "sch": {"A1_ltd": [{"k": "shead", "t": "Appendix 1A - Schedule of Professional Services: Compilation of Statutory Financial Statements"}, {"k": "cont", "t": "The purpose of this schedule to our engagement letter is to set out the basis on which we are to compile the statutory financial statements for {{client}} (the company)."}, {"k": "shead", "t": "1.\tResponsibilities of the Directors", "ind": 540}, {"k": "snum", "t": "1.1\tAs directors of the above company, in addition to your general duties specified in section 170 to 177 of the Companies Act 2006, you are responsible for keeping adequate accounting records that are sufficient to show and explain the company's transactions and disclose with reasonable accuracy at any time the financial position of the company and to enable you to ensure that the financial statements comply with the Companies Act 2006. You are also responsible for preparing financial statements which give a true and fair view, have been prepared in accordance with United Kingdom Accounting Standards (United Kingdom Generally Accepted Accounting Practice) and the Companies Act 2006 and regulations made under it."}, {"k": "snum", "t": "1.2\tIn preparing the financial statements, you are required to:-"}, {"k": "bullet", "t": "select suitable accounting policies and then apply them consistently;"}, {"k": "bullet", "t": "make judgements and estimates that are reasonable and prudent; and"}, {"k": "bullet", "t": "prepare the financial statements on the going concern basis unless it is inappropriate to presume that the company will continue in business."}, {"k": "snum", "t": "1.3\tYou also have a responsibility not to approve these financial statements unless you are satisfied that they give a true and fair view of the assets, liabilities, financial position and profit and loss of the company."}, {"k": "snum", "t": "1.4\tYour responsibility for preparation of the financial statements extends to the application of exemptions and options on transition to, and application of, new accounting standards. As directors of the company you should also consider the impact of new accounting standards on the business, including the impact on going concern."}, {"k": "snum", "t": "1.5\tYou are responsible for safeguarding the assets of the company and hence for taking reasonable steps for the prevention and detection of fraud and other irregularities."}, {"k": "snum", "t": "1.6\tYou are also responsible for determining whether, in respect of the year, the company meets the conditions for exemption from an audit of the financial statements set out in section 477 of the Companies Act 2006, and for determining whether, in respect of the year, the exemption is not available for any of the reasons set out in sections 476, 478 and 479."}, {"k": "snum", "t": "1.7\tYou are responsible for ensuring that the company complies with the laws and regulations that apply to its activities, and for preventing non-compliance and for detecting any that occurs."}, {"k": "snum", "t": "1.8\tYou have undertaken to make available to us, as and when required, all the company's accounting records and related financial information, including minutes of management and shareholders' meetings necessary for the compilation of the financial statements. You will make full disclosure to us of all relevant information."}, {"k": "snum", "t": "1.9\tYou have agreed that your staff will be responsible for:-"}, {"k": "bullet", "t": "keeping the record of receipts and payments;"}, {"k": "bullet", "t": "reconciling the balances monthly with the bank statements;"}, {"k": "bullet", "t": "keeping posted and balanced the purchase and sales ledgers;"}, {"k": "bullet", "t": "preparing a detailed list of ledger balances;"}, {"k": "bullet", "t": "preparing details of the annual stocktaking suitably priced and extended."}, {"k": "snum", "t": "1.10\tWhere financial information is to be published, which includes a report by us or is otherwise connected to us, on the company's website or by other electronic means, it is your responsibility to advise us of the intended electronic publication before it occurs and to ensure that any such publication properly presents the financial information and our report. We reserve the right to withhold consent to the electronic publication of our report if it, or the financial statements, are to be published in an inappropriate manner. It is your responsibility to ensure there are controls in place to prevent or detect quickly any changes to that information. We are not required to review such controls nor to carry out ongoing reviews of the information after it is first published. The maintenance and integrity of the company's website is your responsibility and we accept no responsibility for changes made to such information after it is first posted."}, {"k": "shead", "t": "2.\tResponsibilities of the Accountants", "ind": 540}, {"k": "snum", "t": "2.1\tAs the company is totally exempt from audit, we have no statutory responsibilities to the company at all. Our only responsibilities arise from those specifically agreed upon between us in respect of other professional services."}, {"k": "snum", "t": "2.2\tYou have asked us to help you prepare the financial statements in accordance with the requirements of the Companies Act 2006. We will compile the annual financial statements for your approval based on the accounting records maintained by you and the information and explanations given to us by you. We shall plan our work on the basis that no report on the financial statements is required by statute or regulation for the year, unless you inform us in writing to the contrary. In carrying out our engagement we will make enquiries of management and undertake any procedures that we judge appropriate but are under no obligation to perform procedures that may be required for assurance engagements such as audits or reviews."}, {"k": "snum", "t": "2.3\tYou have advised us that the company is exempt from an audit of the financial statements. We will not check whether this is the case. However, should our work indicate that the company is not entitled to the exemption, we will inform you of this."}, {"k": "snum", "t": "2.4\tOur work will not be an audit of the financial statements in accordance with the International Standards on Auditing (UK and Ireland). Consequently, our work will not provide any assurance that the accounting records or the financial statements are free from material misstatement, whether caused by fraud, other irregularities or error and cannot be relied on to identify weaknesses in internal controls."}, {"k": "snum", "t": "2.5\tSince we will not carry out an audit, nor confirm in any way the accuracy or reasonableness of the accounting records maintained by the company, we are unable to provide any assurance as to whether the financial statements that we prepare from those records present a true and fair view. We will, however, advise you on whether your records are adequate for the preparation of financial statements and recommend improvements."}, {"k": "snum", "t": "2.6\tWe have a professional duty to compile financial statements that conform with generally accepted accounting principles from the accounting records and information and explanations given to us. Furthermore, as directors, you have a duty to prepare financial statements that comply with the Companies Act 2006, regulations made under that Act and United Kingdom Accounting Standards (United Kingdom Generally Accepted Accounting Practice (UK GAAP)). Where we identify that the financial statements do not conform to UK GAAP or if the accounting policies adopted are not immediately apparent this will need to be disclosed in the financial statements."}, {"k": "snum", "t": "2.7\tWe also have a professional responsibility not to allow our name to be associated with financial statements which we believe may be misleading. Therefore, although we are not required to search for such matters, should we become aware, for any reason, that the financial statements may be misleading, we will discuss the matter with you with a view to agreeing appropriate adjustments and/or disclosures in the financial statements. In circumstances where adjustments and/or disclosures that we consider appropriate are not made or where we are not provided with appropriate information, and as a result we consider that the financial statements are misleading, we will withdraw from the engagement."}, {"k": "snum", "t": "2.8\tAs part of our normal procedures, we may request you to provide written confirmation of any information or explanations given by you orally during the course of our work."}, {"k": "shead", "t": "3.\tForm of the Accountants' Report", "ind": 540}, {"k": "snum", "t": "3.1\tWe shall report to the Board of Directors, with any modifications that we consider may be necessary, that in accordance with this engagement letter and in order to assist you to fulfil your responsibilities, we have compiled, without carrying out an audit, the financial statements from the accounting records of the company and from the information and explanations supplied to us. To the fullest extent permitted by law we do not accept or assume responsibility to anyone other than the company and the company's Board of Directors, as a body, for the work or for this report."}, {"k": "shead", "t": "4.\tOther Accounting Services", "ind": 540}, {"k": "snum", "t": "4.1\tWe will also carry out the following services as your agents on the basis that you will make full disclosure to us of all relevant information:-"}, {"k": "bullet", "t": "providing assistance in preparing and lodging returns with the Registrar of Companies; and"}, {"k": "bullet", "t": "investigating irregularities and fraud upon receiving specific instructions."}], "A1_uninc_sole": [{"k": "shead", "t": "Appendix 1A - Schedule of Professional Services: Compilation of Unaudited Financial Statements"}, {"k": "cont", "t": "The purpose of this schedule to our engagement letter is to set out the basis on which we are to compile the unaudited financial information for {{clientPerson}} (the business)."}, {"k": "shead", "t": "1.\tYour Responsibilities", "ind": 540}, {"k": "snum", "t": "1.1\tYou will be responsible for the reliability, accuracy and completeness of the accounting records."}, {"k": "snum", "t": "1.2\tYou have undertaken to make available to us, as and when required, all of your accounting records and related financial information necessary to carry out our work. You will provide us with all information and explanations relevant to the purpose and compilation of the financial information, and you will disclose to us all relevant information in full."}, {"k": "snum", "t": "1.3\tYou are responsible for ensuring that, to the best of your knowledge and belief, financial information, whether used by the business or for the financial statements, is accurate and complete. You are also responsible for ensuring that the activities of the business are conducted honestly, and for safeguarding the assets of the business and for taking reasonable steps to prevent and detect fraud and other irregularities."}, {"k": "snum", "t": "1.4\tYou are responsible for ensuring that the business complies with the laws and regulations that apply to its activities, and for preventing non-compliance, and for detecting any that occurs."}, {"k": "shead", "t": "2.\tOur Responsibilities", "ind": 540}, {"k": "snum", "t": "2.1\tYou have asked us to prepare a profit and loss account, balance sheet and relevant notes to enable profits to be calculated such as to meet the requirements of section 25 of the Income Tax (Trading and Other Income) Act 2005 and which provides sufficient and relevant information to enable the completion of a tax return. We will compile the financial information for your approval based on the accounting records maintained by you and the information and explanations given to us by you."}, {"k": "snum", "t": "2.2\tWe shall plan our work on the basis that no report is required by statute or regulation, unless you inform us in writing to the contrary. In carrying out our engagement we will make enquiries and undertake any procedures that we judge appropriate but are under no obligation to perform procedures that may be required for assurance engagements such as audits or reviews."}, {"k": "snum", "t": "2.3\tOur work will not be an audit of the financial information in accordance with International Standards on Auditing (UK and Ireland). Consequently, our work will not provide any assurance that the accounting records or the financial information are free from material misstatement, whether caused by fraud, other irregularities or error and cannot be relied on to identify weaknesses in internal controls."}, {"k": "snum", "t": "2.4\tSince we have not carried out an audit, nor confirmed in any way the accuracy or reasonableness of the accounting records maintained by you, we are unable to provide any assurance as to whether the financial information that we prepare from those records presents a true and fair view. We will, however, advise you on whether your records are adequate for the preparation of the financial information and recommend improvements."}, {"k": "snum", "t": "2.5\tWe have a professional duty to compile financial information that conforms with the generally accepted accounting principles selected by management as being appropriate for the purpose for which the information is prepared. The financial reporting framework on which the information has been compiled, its purpose and limitations will be disclosed in an accounting policy note to the financial information and will be referred to in our accountants' report."}, {"k": "snum", "t": "2.6\tWe also have a professional responsibility not to allow our name to be associated with financial information which we believe may be misleading. Therefore, although we are not required to search for such matters, should we become aware, for any reason, that the financial information may be misleading, we will discuss the matter with you with a view to agreeing appropriate adjustments and/or disclosures in the financial information. In circumstances where adjustments and/or disclosures that we consider appropriate are not made or where we are not provided with appropriate information, and as a result we consider that the financial information is misleading, we will withdraw from the engagement."}, {"k": "snum", "t": "2.7\tAs part of our normal procedures, we may request you to provide written confirmation of any information or explanations given by you orally during the course of our work."}, {"k": "snum", "t": "2.8\tYou will approve and sign the financial information thereby acknowledging responsibility for it, including the appropriateness of the financial reporting framework on which it has been compiled, and for providing us with all information and explanations necessary for its compilation."}, {"k": "shead", "t": "3.\tForm of Our Report", "ind": 540}, {"k": "snum", "t": "3.1\tWe shall report to you that in accordance with this engagement letter we have compiled, without carrying out an audit, the financial information from the accounting records of the entity and from the information and explanations supplied to us. The report should not be used for any purpose other than as set out in this engagement letter. To the fullest extent permitted by law we do not accept or assume responsibility to anyone other than the addressee of the report, for our work or for our report."}], "A1_uninc_psh": [{"k": "shead", "t": "Appendix 1A - Schedule of Professional Services: Compilation of Unaudited Financial Statements"}, {"k": "cont", "t": "The purpose of this schedule to our engagement letter is to set out the basis on which we are to compile the unaudited financial information for {{client}} (the business)."}, {"k": "shead", "t": "1.\tYour Responsibilities", "ind": 540}, {"k": "snum", "t": "1.1\tYou will be responsible for the reliability, accuracy and completeness of the accounting records."}, {"k": "snum", "t": "1.2\tYou have undertaken to make available to us, as and when required, all of your accounting records and related financial information necessary to carry out our work. You will provide us with all information and explanations relevant to the purpose and compilation of the financial information, and you will disclose to us all relevant information in full."}, {"k": "snum", "t": "1.3\tYou are responsible for ensuring that, to the best of your knowledge and belief, financial information, whether used by the business or for the financial statements, is accurate and complete. You are also responsible for ensuring that the activities of the business are conducted honestly, and for safeguarding the assets of the business and for taking reasonable steps to prevent and detect fraud and other irregularities."}, {"k": "snum", "t": "1.4\tYou are responsible for ensuring that the business complies with the laws and regulations that apply to its activities, and for preventing non-compliance, and for detecting any that occurs."}, {"k": "shead", "t": "2.\tOur Responsibilities", "ind": 540}, {"k": "snum", "t": "2.1\tYou have asked us to prepare a profit and loss account, balance sheet and relevant notes to enable profits to be calculated such as to meet the requirements of section 25 of the Income Tax (Trading and Other Income) Act 2005 and which provides sufficient and relevant information to enable the completion of a tax return. We will compile the financial information for your approval based on the accounting records maintained by you and the information and explanations given to us by you."}, {"k": "snum", "t": "2.2\tWe shall plan our work on the basis that no report is required by statute or regulation, unless you inform us in writing to the contrary. In carrying out our engagement we will make enquiries and undertake any procedures that we judge appropriate but are under no obligation to perform procedures that may be required for assurance engagements such as audits or reviews."}, {"k": "snum", "t": "2.3\tOur work will not be an audit of the financial information in accordance with International Standards on Auditing (UK and Ireland). Consequently, our work will not provide any assurance that the accounting records or the financial information are free from material misstatement, whether caused by fraud, other irregularities or error and cannot be relied on to identify weaknesses in internal controls."}, {"k": "snum", "t": "2.4\tSince we have not carried out an audit, nor confirmed in any way the accuracy or reasonableness of the accounting records maintained by you, we are unable to provide any assurance as to whether the financial information that we prepare from those records presents a true and fair view. We will, however, advise you on whether your records are adequate for the preparation of the financial information and recommend improvements."}, {"k": "snum", "t": "2.5\tWe have a professional duty to compile financial information that conforms with the generally accepted accounting principles selected by management as being appropriate for the purpose for which the information is prepared. The financial reporting framework on which the information has been compiled, its purpose and limitations will be disclosed in an accounting policy note to the financial information and will be referred to in our accountants' report."}, {"k": "snum", "t": "2.6\tWe also have a professional responsibility not to allow our name to be associated with financial information which we believe may be misleading. Therefore, although we are not required to search for such matters, should we become aware, for any reason, that the financial information may be misleading, we will discuss the matter with you with a view to agreeing appropriate adjustments and/or disclosures in the financial information. In circumstances where adjustments and/or disclosures that we consider appropriate are not made or where we are not provided with appropriate information, and as a result we consider that the financial information is misleading, we will withdraw from the engagement."}, {"k": "snum", "t": "2.7\tAs part of our normal procedures, we may request you to provide written confirmation of any information or explanations given by you orally during the course of our work."}, {"k": "snum", "t": "2.8\tYou will approve and sign the financial information thereby acknowledging responsibility for it, including the appropriateness of the financial reporting framework on which it has been compiled, and for providing us with all information and explanations necessary for its compilation."}, {"k": "shead", "t": "3.\tForm of Our Report", "ind": 540}, {"k": "snum", "t": "3.1\tWe shall report to you that in accordance with this engagement letter we have compiled, without carrying out an audit, the financial information from the accounting records of the entity and from the information and explanations supplied to us. The report should not be used for any purpose other than as set out in this engagement letter. To the fullest extent permitted by law we do not accept or assume responsibility to anyone other than the addressee of the report, for our work or for our report."}], "B_ct_novat": [{"k": "shead", "t": "Appendix 1B - Schedule of Professional Services: Taxation"}, {"k": "cont", "t": "The purpose of this schedule to our engagement letter is to set out the basis on which we are to provide taxation services as your agents on the basis that you will make full disclosure to us of all relevant information."}, {"k": "shead", "t": "1.\tTaxation Services", "ind": 540}, {"k": "snum", "t": "1.1\tWe shall prepare, in respect of each accounting period of the company, a computation for corporation tax purposes adjusted in accordance with the provisions of the Taxes Acts. We shall also prepare the return form CT600 and subsidiary forms required by self assessment. The self assessment forms, together with supporting corporation tax computations, will be sent to you for written approval and signature prior to submission to HM Revenue & Customs in the required iXBRL format."}, {"k": "snum", "t": "1.2\tWe will convert your financial statements into the required iXBRL format appropriate for the purpose of submission of the financial statements to HMRC. We will provide you with detailed information regarding the tagging applied for your approval."}, {"k": "snum", "t": "1.3\tWe shall advise you as to appropriate payments of corporation tax and S455 CTA2010 liabilities (loans to participators)."}, {"k": "snum", "t": "1.4\tIf the company is selected for enquiry by the HM Revenue & Customs, we will agree separate terms of engagement. The supplementary engagement terms will include responsibilities and fees as appropriate."}, {"k": "snum", "t": "1.5\tYou will be responsible, unless otherwise agreed, for all other returns, more particularly, returns relating to employee taxes under PAYE, returns of employee expenses and benefits on forms P11D and the returns of income tax deducted at source as required on forms CT61. Your staff will deal with all returns and other requirements in relation to value added tax."}, {"k": "snum", "t": "1.6\tWe shall be pleased to advise you on matters relating to the company's corporation tax liability, the implications of particular business transactions and on other taxation matters which you refer to us, such as national insurance, income tax deducted at source, employee benefits, value added tax and inheritance tax. Such services would also be subject to separate terms of engagement."}], "B_ct_vat": [{"k": "shead", "t": "Appendix 1B - Schedule of Professional Services: Taxation"}, {"k": "cont", "t": "The purpose of this schedule to our engagement letter is to set out the basis on which we are to provide taxation services as your agents on the basis that you will make full disclosure to us of all relevant information."}, {"k": "shead", "t": "1.\tTaxation Services", "ind": 540}, {"k": "snum", "t": "1.1\tWe shall prepare, in respect of each accounting period of the company, a computation for corporation tax purposes adjusted in accordance with the provisions of the Taxes Acts. We shall also prepare the return form CT600 and subsidiary forms required by self assessment. The self assessment forms, together with supporting corporation tax computations, will be sent to you for written approval and signature prior to submission to HM Revenue & Customs in the required iXBRL format."}, {"k": "snum", "t": "1.2\tWe will convert your financial statements into the required iXBRL format appropriate for the purpose of submission of the financial statements to HMRC. We will provide you with detailed information regarding the tagging applied for your approval."}, {"k": "snum", "t": "1.3\tWe shall advise you as to appropriate payments of corporation tax and S455 CTA2010 liabilities (loans to participators)."}, {"k": "snum", "t": "1.4\tIf the company is selected for enquiry by the HM Revenue & Customs, we will agree separate terms of engagement. The supplementary engagement terms will include responsibilities and fees as appropriate."}, {"k": "snum", "t": "1.5\tYou will be responsible, unless otherwise agreed, for all other returns, more particularly, returns relating to employee taxes under PAYE, returns of employee expenses and benefits on forms P11D and the returns of income tax deducted at source as required on forms CT61. We will assist with all returns and other requirements in relation to value added tax."}, {"k": "snum", "t": "1.6\tWe shall be pleased to advise you on matters relating to the company's corporation tax liability, the implications of particular business transactions and on other taxation matters which you refer to us, such as national insurance, income tax deducted at source, employee benefits, value added tax and inheritance tax. Such services would also be subject to separate terms of engagement."}], "B_ct_novat_payroll": [{"k": "shead", "t": "Appendix 1B - Schedule of Professional Services: Taxation"}, {"k": "cont", "t": "The purpose of this schedule to our engagement letter is to set out the basis on which we are to provide taxation services as your agents on the basis that you will make full disclosure to us of all relevant information."}, {"k": "shead", "t": "1.\tTaxation Services", "ind": 540}, {"k": "snum", "t": "1.1\tWe shall prepare, in respect of each accounting period of the company, a computation for corporation tax purposes adjusted in accordance with the provisions of the Taxes Acts. We shall also prepare the return form CT600 and subsidiary forms required by self assessment. The self assessment forms, together with supporting corporation tax computations, will be sent to you for written approval and signature prior to submission to HM Revenue & Customs in the required iXBRL format."}, {"k": "snum", "t": "1.2\tWe will convert your financial statements into the required iXBRL format appropriate for the purpose of submission of the financial statements to HMRC. We will provide you with detailed information regarding the tagging applied for your approval."}, {"k": "snum", "t": "1.3\tWe shall advise you as to appropriate payments of corporation tax and S455 CTA2010 liabilities (loans to participators)."}, {"k": "snum", "t": "1.4\tIf the company is selected for enquiry by the HM Revenue & Customs, we will agree separate terms of engagement. The supplementary engagement terms will include responsibilities and fees as appropriate."}, {"k": "snum", "t": "1.5\tYou will be responsible, unless otherwise agreed, for all other returns. It has been agreed that we shall assist with the preparation of returns relating to employee taxes under PAYE, returns of employee expenses and benefits on forms P11D and the returns of income tax deducted at source as required on forms CT61. Your staff will deal with all returns and other requirements in relation to value added tax."}, {"k": "snum", "t": "1.6\tWe shall be pleased to advise you on matters relating to the company's corporation tax liability, the implications of particular business transactions and on other taxation matters which you refer to us, such as national insurance, income tax deducted at source, employee benefits, value added tax and inheritance tax. Such services would also be subject to separate terms of engagement."}], "B_ct_vat_payroll": [{"k": "shead", "t": "Appendix 1B - Schedule of Professional Services: Taxation"}, {"k": "cont", "t": "The purpose of this schedule to our engagement letter is to set out the basis on which we are to provide taxation services as your agents on the basis that you will make full disclosure to us of all relevant information."}, {"k": "shead", "t": "1.\tTaxation Services", "ind": 540}, {"k": "snum", "t": "1.1\tWe shall prepare, in respect of each accounting period of the company, a computation for corporation tax purposes adjusted in accordance with the provisions of the Taxes Acts. We shall also prepare the return form CT600 and subsidiary forms required by self assessment. The self assessment forms, together with supporting corporation tax computations, will be sent to you for written approval and signature prior to submission to HM Revenue & Customs in the required iXBRL format."}, {"k": "snum", "t": "1.2\tWe will convert your financial statements into the required iXBRL format appropriate for the purpose of submission of the financial statements to HMRC. We will provide you with detailed information regarding the tagging applied for your approval."}, {"k": "snum", "t": "1.3\tWe shall advise you as to appropriate payments of corporation tax and S455 CTA2010 liabilities (loans to participators)."}, {"k": "snum", "t": "1.4\tIf the company is selected for enquiry by the HM Revenue & Customs, we will agree separate terms of engagement. The supplementary engagement terms will include responsibilities and fees as appropriate."}, {"k": "snum", "t": "1.5\tYou will be responsible, unless otherwise agreed, for all other returns. It has been agreed that we shall assist with the preparation of returns relating to employee taxes under PAYE, returns of employee expenses and benefits on forms P11D and the returns of income tax deducted at source as required on forms CT61. We will also assist with all returns and other requirements in relation to value added tax."}, {"k": "snum", "t": "1.6\tWe shall be pleased to advise you on matters relating to the company's corporation tax liability, the implications of particular business transactions and on other taxation matters which you refer to us, such as national insurance, income tax deducted at source, employee benefits, value added tax and inheritance tax. Such services would also be subject to separate terms of engagement."}], "B_sa_legacy_novat": [{"k": "shead", "t": "Appendix 1B - Schedule of Professional Services: Taxation"}, {"k": "cont", "t": "The purpose of this schedule to our engagement letter is to set out the basis on which we are to provide taxation services as your agents on the basis that you will make full disclosure to us of all relevant information."}, {"k": "shead", "t": "1.\tTaxation Services", "ind": 540}, {"k": "snum", "t": "1.1\tWe shall prepare, in respect of each accounting period, a computation of profits adjusted in accordance with the Taxes Acts. Once they have been approved by you we shall complete the appropriate self assessment schedule."}, {"k": "snum", "t": "1.2\tWe shall prepare on your behalf the necessary self assessment returns including a calculation of your tax liabilities from the information supplied by you. With your agreement we shall obtain some information direct from your"}, {"k": "cont", "t": "bank, building societies, etc."}, {"k": "snum", "t": "1.3\tWe shall forward your return (together with copies of all supporting material we propose to submit to HM Revenue & Customs (HMRC) with your return) to you for approval and signature. You are legally responsible for making a correct return in respect of your annual tax liability, and it is essential that we as your agent are supplied with all relevant information. At this stage we shall advise you as to your outstanding tax liabilities and the appropriate payment dates."}, {"k": "snum", "t": "1.4\tIt is important to note that HMRC will charge interest on any tax paid late, and in some cases can increase any outstanding liability by imposing surcharges."}, {"k": "snum", "t": "1.5\tFurthermore, to avoid automatic late filing penalties, which start at £100, the return must normally be submitted to the Inspector by 31 January following the tax year to which the return relates. This date may be extended if there is an HMRC delay in issuing the return to you."}, {"k": "snum", "t": "1.6\tIt is therefore essential that you respond on a timely basis to any requests for further information to enable us to complete your return and submit it to HMRC on time."}, {"k": "snum", "t": "1.7\tIt is your responsibility to ensure that your tax is paid on time and that your return is filed on time."}, {"k": "shead", "t": "2.\tEnquiries", "ind": 540}, {"k": "snum", "t": "2.1\tWe shall respond on your behalf to any enquiries from HM Revenue & Customs arising from your tax return. However, we shall consult you if it becomes clear that the HM Revenue & Customs are opening an in-depth enquiry. They have the power to do this on a purely random basis."}, {"k": "shead", "t": "3.\tRecord Keeping Requirements", "ind": 540}, {"k": "snum", "t": "3.1\tSelf assessment requires full records supporting a return to be retained until the fifth anniversary of the 31 January following the end of the year assessment concerned. You will be responsible for retaining these records."}, {"k": "cont", "t": "Penalties of up to £3,000 may be imposed for non-compliance with these provisions."}, {"k": "shead", "t": "4.\tOther Services", "ind": 540}, {"k": "snum", "t": "4.1\tWe shall be pleased to give advice on the tax implications of specific matters which you may refer to us from time to time."}, {"k": "snum", "t": "4.2\tYou will be responsible for all other returns, particularly including those relating to employees' taxes, PAYE and VAT. We shall, however, be happy to advise in this connection if specifically requested. Such advice and/or assistance would also be subject to separate terms of engagement."}], "B_sa_legacy_vat": [{"k": "shead", "t": "Appendix 1B - Schedule of Professional Services: Taxation"}, {"k": "cont", "t": "The purpose of this schedule to our engagement letter is to set out the basis on which we are to provide taxation services as your agents on the basis that you will make full disclosure to us of all relevant information."}, {"k": "shead", "t": "1.\tTaxation Services", "ind": 540}, {"k": "snum", "t": "1.1\tWe shall prepare, in respect of each accounting period, a computation of profits adjusted in accordance with the Taxes Acts. Once they have been approved by you we shall complete the appropriate self assessment schedule."}, {"k": "snum", "t": "1.2\tWe shall prepare on your behalf the necessary self assessment returns including a calculation of your tax liabilities from the information supplied by you. With your agreement we shall obtain some information direct from your"}, {"k": "cont", "t": "bank, building societies, etc."}, {"k": "snum", "t": "1.3\tWe shall forward your return (together with copies of all supporting material we propose to submit to HM Revenue & Customs (HMRC) with your return) to you for approval and signature. You are legally responsible for making a correct return in respect of your annual tax liability, and it is essential that we as your agent are supplied with all relevant information. At this stage we shall advise you as to your outstanding tax liabilities and the appropriate payment dates."}, {"k": "snum", "t": "1.4\tIt is important to note that HMRC will charge interest on any tax paid late, and in some cases can increase any outstanding liability by imposing surcharges."}, {"k": "snum", "t": "1.5\tFurthermore, to avoid automatic late filing penalties, which start at £100, the return must normally be submitted to the Inspector by 31 January following the tax year to which the return relates. This date may be extended if there is an HMRC delay in issuing the return to you."}, {"k": "snum", "t": "1.6\tIt is therefore essential that you respond on a timely basis to any requests for further information to enable us to complete your return and submit it to HMRC on time."}, {"k": "snum", "t": "1.7\tIt is your responsibility to ensure that your tax is paid on time and that your return is filed on time."}, {"k": "shead", "t": "2.\tEnquiries", "ind": 540}, {"k": "snum", "t": "2.1\tWe shall respond on your behalf to any enquiries from HM Revenue & Customs arising from your tax return. However, we shall consult you if it becomes clear that the HM Revenue & Customs are opening an in-depth enquiry. They have the power to do this on a purely random basis."}, {"k": "shead", "t": "3.\tRecord Keeping Requirements", "ind": 540}, {"k": "snum", "t": "3.1\tSelf assessment requires full records supporting a return to be retained until the fifth anniversary of the 31 January following the end of the year assessment concerned. You will be responsible for retaining these records."}, {"k": "cont", "t": "Penalties of up to £3,000 may be imposed for non-compliance with these provisions."}, {"k": "shead", "t": "4.\tOther Services", "ind": 540}, {"k": "snum", "t": "4.1\tWe shall be pleased to give advice on the tax implications of specific matters which you may refer to us from time to time."}, {"k": "snum", "t": "4.2\tYou will be responsible for all other returns, particularly including those relating to employees' taxes, PAYE and VAT. We will assist with all returns and other requirements in relation to value added tax."}], "B_sa_mtd": [{"k": "shead", "t": "Appendix 1B - Schedule of Professional Services: Taxation"}, {"k": "cont", "t": "The purpose of this schedule to our engagement letter is to set out the basis on which we are to provide taxation services as your agents on the basis that you will make full disclosure to us of all relevant information."}, {"k": "shead", "t": "1.\tYour Responsibilities", "ind": 540}, {"k": "snum", "t": "1.1\tYou are legally responsible for making a correct return in respect of your annual tax liability, and it is essential that we as your agent are supplied with all relevant information."}, {"k": "snum", "t": "1.2\tYou are no less responsible for errors in unapproved returns, submitted on the basis of the information provided to and processed by us, than if you had confirmed your approval of the returns."}, {"k": "snum", "t": "1.3\tIt is your responsibility to ensure that your tax is paid on time and that your return is filed on time."}, {"k": "snum", "t": "1.4\tSelf assessment requires full records supporting a return to be retained until the fifth anniversary of the 31 January following the end of the year assessment concerned. You will be responsible for retaining these records. Penalties of up to £3,000 may be imposed for non-compliance with these provisions."}, {"k": "snum", "t": "1.5\tYou are responsible for monitoring {{possAdj}} monthly turnover to establish whether you are liable to register {{objPro}} for VAT. If you do not understand what you need to do, please ask us. If you exceed the UK VAT registration threshold, and you wish us to assist you in notifying HMRC of your liability to be VAT registered, you must give us clear instructions to assist you in the VAT registration process. You should notify us of your instructions in good time to enable the VAT registration application form to be submitted within the statutory time limit of one month following the month in which you exceeded the VAT registration threshold in force at that time. We will not be responsible if you fail to notify us in time and incur a late registration penalty as a result. The same applies for equivalent non-UK taxes."}, {"k": "snum", "t": "1.6\tYou are responsible for employment taxes, pensions and the assessment of the employment status of your workers. If you do not understand what you need to consider or what action you need to take, please ask us. We will not be in a position to assist you in complying with your responsibilities if we are not engaged to provide such a service."}, {"k": "snum", "t": "1.7\tWhere we are keeping your digital accounts records you are responsible for providing us in a timely manner with the information required for us to prepare the records."}, {"k": "snum", "t": "1.8\tYou agree to maintain your accounting records in a suitable digital format in order to satisfy the requirements of Making Tax Digital for Income Tax."}, {"k": "cont", "t": "2 Our Responsibilities"}, {"k": "snum", "t": "2.1\tWe shall prepare the quarterly updates required under Making Tax Digital for Income Tax. Once they have been approved by you we shall submit these to HM Revenue & Customs (HMRC)."}, {"k": "snum", "t": "2.2\tWe shall prepare, in respect of each accounting period, a computation of profits adjusted in accordance with the Taxes Acts. Once they have been approved by you we shall complete the appropriate self assessment schedule."}, {"k": "snum", "t": "2.3\tWe shall prepare on your behalf the necessary year-end tax return including a calculation of your tax liabilities from the information supplied by you. With your agreement we shall obtain some information direct from your bank, building societies etc."}, {"k": "snum", "t": "2.4\tWe shall forward your return (together with copies of all supporting material we propose to submit to HMRC with your return) to you for written approval, as the legal responsibility for approval of the return cannot be delegated to others. At this stage we shall advise you as to your outstanding tax liabilities and the appropriate payment dates."}, {"k": "snum", "t": "2.5\tWe shall also send reminders to you as each payment date approaches."}, {"k": "snum", "t": "2.6\tIt is important to note that HMRC will charge interest on any tax paid late, and in some cases can increase any outstanding liability by imposing surcharges."}, {"k": "snum", "t": "2.7\tFurthermore, to avoid automatic late filing penalties, which start at £100, the return must normally be submitted to the Inspector by 31 January following the tax year to which the return relates. This date may be extended if there is an HMRC delay in issuing the return to you."}, {"k": "snum", "t": "2.8\tIt is therefore essential that you respond on a timely basis to any requests for further information to enable us to complete your return and submit it to HMRC on time."}, {"k": "snum", "t": "2.9\tWith this in mind please sign and return the enclosed form 64-8 which authorises HMRC to send us copies of formal notices relevant to your personal tax position. However, to avoid any confusion, please forward to us any correspondence/taxpayer statements that you receive direct from HMRC."}, {"k": "snum", "t": "2.10\tWe shall respond to any enquiries from HMRC arising from your tax return. We shall consult you if it becomes clear that HMRC are opening an enquiry. HMRC have the power to do this on a purely random basis. If you are selected for enquiry by the HMRC, we will agree separate terms of engagement. The supplementary engagement terms will include responsibilities and fees as appropriate."}, {"k": "snum", "t": "2.11\tSince 17 July 2013 a General Anti-Abuse Rule has been in operation in the UK. This rule enables HMRC to further tackle abusive tax planning schemes. Due to the low probability of eventual success of such schemes and the high ethical standards of this firm, it is our policy not to advise on tax schemes that we consider to be artificial or aggressive in nature. Please let us know if you would like to discuss this matter further or if you feel that you are disadvantaged in any way by the firm's policy on tax avoidance."}, {"k": "snum", "t": "2.12\tWe shall be pleased to give advice on the tax implications of specific matters which you may refer to us from time to time, such as national insurance, income tax deducted at source, employee benefits including pensions auto-enrolment, value added tax and inheritance tax. Such advice and / or assistance would also be subject to separate terms of engagement."}, {"k": "snum", "t": "2.13\tWhere specialist advice is required on occasions we may need to seek this from or refer you to appropriate specialists."}], "B_ind_legacy": [{"k": "shead", "t": "Appendix 1A - Schedule of Professional Services: Taxation"}, {"k": "cont", "t": "The purpose of this schedule to our engagement letter is to set out the basis on which we are to provide taxation services as your agents on the basis that you will make full disclosure to us of all relevant information."}, {"k": "shead", "t": "1.\tTaxation Services", "ind": 540}, {"k": "snum", "t": "1.1\tWe shall prepare, in respect of each tax year an income tax computation adjusted in accordance with the Taxes Acts. Once they have been approved by you we shall complete the appropriate self assessment schedule."}, {"k": "snum", "t": "1.2\tWe shall prepare on your behalf the necessary self assessment returns including a calculation of your tax liabilities from the information supplied by you."}, {"k": "cont", "t": "We shall forward your return (together with copies of all supporting material we propose to submit to HM Revenue & Customs with your return) to you for approval and signature. You are legally responsible for making a correct return in respect of your annual tax liability, and it is essential that we as your agent are supplied with all relevant information. At this stage we shall advise you as to your outstanding tax liabilities and the appropriate payment dates."}, {"k": "snum", "t": "1.3\tIt is your responsibility to ensure that your tax is paid on time and that"}, {"k": "cont", "t": "your return is filed on time."}, {"k": "cont", "t": "Consequently, it is your responsibility to provide us with information on a timely basis. We will guarantee to file all returns on time should all information be provided to us by 31st August each year prior to the filing deadline."}, {"k": "snum", "t": "1.4\tEnquiries"}, {"k": "cont", "t": "We shall respond on your behalf to any enquiries from HM Revenue & Customs arising from your tax return. However, if it becomes clear that HM Revenue & Customs are opening an in-depth enquiry, it may be necessary to supply us with any additional information that HM Revenue & Customs so require. We will keep you informed as to the progress of such enquiries."}, {"k": "snum", "t": "1.5\tOther Services"}, {"k": "cont", "t": "We shall be pleased to give advice on the tax implications of specific matters which you may refer to us from time to time."}, {"k": "snum", "t": "1.6\tYour Responsibilities"}, {"k": "cont", "t": "You have undertaken to make available to us, as and when required, all the appropriate records and related financial information necessary for the compilation of the tax return. You will make full disclosure to us of all relevant information. The tax return needs to be approved by you before we are able to submit to HM Revenue & Customs."}, {"k": "snum", "t": "1.7\tYou are responsible for ensuring that, to the best of your knowledge and belief, the information is reliable. You are also responsible for ensuring that activities are conducted honestly."}], "B_ind_mtd": [{"k": "shead", "t": "Appendix 1A - Schedule of Professional Services: Taxation"}, {"k": "cont", "t": "The purpose of this schedule to our engagement letter is to set out the basis on which we are to provide taxation services as your agents on the basis that you will make full disclosure to us of all relevant information."}, {"k": "shead", "t": "1.\tYour Responsibilities", "ind": 540}, {"k": "snum", "t": "1.1\tYou are legally responsible for making a correct return in respect of your annual tax liability, and it is essential that we as your agent are supplied with all relevant information."}, {"k": "snum", "t": "1.2\tYou are no less responsible for errors in unapproved returns, submitted on the basis of the information provided to and processed by us, than if you had confirmed your approval of the returns."}, {"k": "snum", "t": "1.3\tIt is your responsibility to ensure that your tax is paid on time and that your return is filed on time."}, {"k": "snum", "t": "1.4\tSelf assessment requires full records supporting a return to be retained until the fifth anniversary of the 31 January following the end of the year assessment concerned. You will be responsible for retaining these records. Penalties of up to £3,000 may be imposed for non-compliance with these provisions."}, {"k": "snum", "t": "1.5\tYou are responsible for monitoring {{possAdj}} monthly turnover to establish whether you are liable to register {{objPro}} for VAT. If you do not understand what you need to do, please ask us. If you exceed the UK VAT registration threshold, and you wish us to assist you in notifying HMRC of your liability to be VAT registered, you must give us clear instructions to assist you in the VAT registration process. You should notify us of your instructions in good time to enable the VAT registration application form to be submitted within the statutory time limit of one month following the month in which you exceeded the VAT registration threshold in force at that time. We will not be responsible if you fail to notify us in time and incur a late registration penalty as a result. The same applies for equivalent non-UK taxes."}, {"k": "snum", "t": "1.6\tYou are responsible for employment taxes, pensions and the assessment of the employment status of your workers. If you do not understand what you need to consider or what action you need to take, please ask us. We will not be in a position to assist you in complying with your responsibilities if we are not engaged to provide such a service."}, {"k": "snum", "t": "1.7\tWhere we are keeping your digital accounts records you are responsible for providing us in a timely manner with the information required for us to prepare the records."}, {"k": "snum", "t": "1.8\tYou agree to maintain your accounting records in a suitable digital format in order to satisfy the requirements of Making Tax Digital for Income Tax."}, {"k": "cont", "t": "2 Our Responsibilities"}, {"k": "snum", "t": "2.1\tWe shall prepare the quarterly updates required under Making Tax Digital for Income Tax. Once they have been approved by you we shall submit these to HM Revenue & Customs (HMRC)."}, {"k": "snum", "t": "2.2\tWe shall prepare, in respect of each accounting period, a computation of profits adjusted in accordance with the Taxes Acts. Once they have been approved by you we shall complete the appropriate self assessment schedule."}, {"k": "snum", "t": "2.3\tWe shall prepare on your behalf the necessary year-end tax return including a calculation of your tax liabilities from the information supplied by you. With your agreement we shall obtain some information direct from your bank, building societies etc."}, {"k": "snum", "t": "2.4\tWe shall forward your return (together with copies of all supporting material we propose to submit to HMRC with your return) to you for written approval, as the legal responsibility for approval of the return cannot be delegated to others. At this stage we shall advise you as to your outstanding tax liabilities and the appropriate payment dates."}, {"k": "snum", "t": "2.5\tWe shall also send reminders to you as each payment date approaches."}, {"k": "snum", "t": "2.6\tIt is important to note that HMRC will charge interest on any tax paid late, and in some cases can increase any outstanding liability by imposing surcharges."}, {"k": "snum", "t": "2.7\tFurthermore, to avoid automatic late filing penalties, which start at £100, the return must normally be submitted to the Inspector by 31 January following the tax year to which the return relates. This date may be extended if there is an HMRC delay in issuing the return to you."}, {"k": "snum", "t": "2.8\tIt is therefore essential that you respond on a timely basis to any requests for further information to enable us to complete your return and submit it to HMRC on time."}, {"k": "snum", "t": "2.9\tWith this in mind please sign and return the enclosed form 64-8 which authorises HMRC to send us copies of formal notices relevant to your personal tax position. However, to avoid any confusion, please forward to us any correspondence/taxpayer statements that you receive direct from HMRC."}, {"k": "snum", "t": "2.10\tWe shall respond to any enquiries from HMRC arising from your tax return. We shall consult you if it becomes clear that HMRC are opening an enquiry. HMRC have the power to do this on a purely random basis. If you are selected for enquiry by the HMRC, we will agree separate terms of engagement. The supplementary engagement terms will include responsibilities and fees as appropriate."}, {"k": "snum", "t": "2.11\tSince 17 July 2013 a General Anti-Abuse Rule has been in operation in the UK. This rule enables HMRC to further tackle abusive tax planning schemes. Due to the low probability of eventual success of such schemes and the high ethical standards of this firm, it is our policy not to advise on tax schemes that we consider to be artificial or aggressive in nature. Please let us know if you would like to discuss this matter further or if you feel that you are disadvantaged in any way by the firm's policy on tax avoidance."}, {"k": "snum", "t": "2.12\tWe shall be pleased to give advice on the tax implications of specific matters which you may refer to us from time to time, such as national insurance, income tax deducted at source, employee benefits including pensions auto-enrolment, value added tax and inheritance tax. Such advice and / or assistance would also be subject to separate terms of engagement."}, {"k": "snum", "t": "2.13\tWhere specialist advice is required on occasions we may need to seek this from or refer you to appropriate specialists."}], "payroll": [{"k": "shead", "t": "Appendix 1C - Schedule of Professional Services: Payroll Services"}, {"k": "cont", "t": "This schedule should be read in conjunction with the engagement letter and the terms of business.", "ind": 540, "flat": true}, {"k": "shead", "t": "1.\tResponsibilities and Scope for Payroll Services", "ind": 540}, {"k": "snum", "t": "1.1\tRecurring Compliance Work", "bold": true, "ind": 540}, {"k": "cont", "t": "We will prepare your UK payroll for each payroll period to meet UK employment tax requirements, specifically:", "ind": 540, "flat": true}, {"k": "bullet", "t": "calculating the pay as you earn (PAYE) income tax deductions, including at the Scottish and Welsh rate of income tax, if applicable;"}, {"k": "bullet", "t": "calculating the employees' national insurance contributions (NIC) deductions;"}, {"k": "bullet", "t": "calculating the employer's NIC liabilities;"}, {"k": "bullet", "t": "calculating statutory payments, for example, statutory sick pay and/or statutory maternity pay;"}, {"k": "bullet", "t": "calculating reclaims of statutory payments, for example, maternity payments"}, {"k": "bullet", "t": "calculating employee and employer pension contributions for employees who are members of workplace pension schemes (including those who are auto-enrolled) on the basis of the information that you provide to us;"}, {"k": "bullet", "t": "processing any employee and employer pension contribution refunds through the payroll;"}, {"k": "bullet", "t": "calculating other statutory and non-statutory deductions including employment allowance and apprenticeship levy;"}, {"k": "bullet", "t": "submitting information online to HMRC under Real Time Information (RTI) for PAYE; and"}, {"k": "bullet", "t": "Submitting information online to your Pension Scheme."}, {"k": "cont", "t": "Before the time of payment through the payroll or due date, we will prepare and send to you the following documents for delivering information to HMRC:", "ind": 540, "flat": true}, {"k": "bullet", "t": "payroll summary report showing the reconciliation from gross to net for each employee and all relevant payroll totals;"}, {"k": "bullet", "t": "the data included within each Full Payment Submission (FPS) for taxable pay and, where appropriate, payrolled benefits-in-kind and expenses for each employee;"}, {"k": "bullet", "t": "a payslip for each employee;"}, {"k": "bullet", "t": "a form P45 for each leaver;"}, {"k": "bullet", "t": "a report showing your PAYE and NIC liability, student loan repayments, apprenticeship levy and due date for payment; and"}, {"k": "bullet", "t": "a workplace pension contributions report showing i) any employee and employer pension contributions payable in respect of each employee to the respective workplace pension scheme(s) of which they are members and the due date(s) for payment; ii) any employee pension contribution refunds payable to any employee; and iii) any employer pension contribution refunds due to you for any employee who has ceased membership of the scheme(s)."}, {"k": "cont", "t": "We will submit FPS online to HMRC on the basis of the data provided by you. (FPS must normally reach HMRC on or before the contractual payday, i.e. the date that employees are entitled to be paid). You must ensure the data provided to us is complete and accurate and your attention is drawn to your legal responsibilities as set out below.", "ind": 540, "flat": true}, {"k": "cont", "t": "For each tax month we will prepare, if appropriate, an Employer Payment Summary (EPS) from the information and explanations that you provide to us. (Examples of EPS data include statutory payments, employment allowance, construction industry scheme deductions, apprenticeship levy allowance allocated to that PAYE scheme and apprenticeship levy payable to date and confirmation that no payments were, or will be, made to employees during that tax month or for future tax months.)", "ind": 540, "flat": true}, {"k": "cont", "t": "We will submit EPS online to HMRC on the basis of the data provided by you. (EPS must reach HMRC by the 19th of the month following the tax month to which they relate.) You must ensure that the data provided to us is complete and accurate and your attention is drawn to your legal responsibilities as set out below.", "ind": 540, "flat": true}, {"k": "cont", "t": "At the end of the tax year we will:", "ind": 540, "flat": true}, {"k": "bullet", "t": "prepare the final FPS (or EPS) and submit this to HMRC on the basis of the data provided by you; (the due date for submitting final FPS is on or before the last contractual payday of the tax year, failing which, the final EPS for the year must reach HMRC by 19 April following the end of the tax year;) you must ensure that the data provided to us is complete and accurate and your attention is drawn to your legal responsibilities as set out below;"}, {"k": "bullet", "t": "prepare and send to you Form P60 for each employee on the payroll at the year-end so you can give them to employees by the statutory due date of 31 May following the end of the tax year;"}, {"k": "bullet", "t": "prepare and send to you a statement for every employee for whom benefits-in-kind have been payrolled identifying every benefit provided to each employee during the tax year and the cash equivalent of each benefit treated as PAYE income so you can give them to employees by the statutory due date of 31 May following the end of the tax year;"}, {"k": "bullet", "t": "give you details of the Class 1A NIC on payrolled benefits-in-kind which will need to be accounted for on form P11D(b) and the due date for payment"}, {"k": "bullet", "t": "give you details of the Class 1A NIC on expenses accounted for in the payroll which will need to be accounted for on form P11D(b) and the due date for payment; and"}, {"k": "bullet", "t": "give you the figures that need to be included on forms P11D to account for income tax in respect of expenses for which Class 1 NIC has been accounted for in the payroll."}, {"k": "cont", "t": "We will deal with any online secure messages sent to us by HMRC in respect of your payroll, for example, code number notifications, student loan repayment notices, and generic notification notices.", "ind": 540, "flat": true}, {"k": "cont", "t": "We will submit national insurance number (NINO) verification requests as appropriate to verify or obtain a NINO for a new employee.", "ind": 540, "flat": true}, {"k": "cont", "t": "Any enquiries from individual employees regarding their pay or other payroll details will be referred back to you.", "ind": 540, "flat": true}, {"k": "snum", "t": "1.2\tExcluded, Ad Hoc and Advisory Work", "bold": true, "ind": 540}, {"k": "cont", "t": "The scope of our services provided to you will be only as set out above, and all other services which we may offer are excluded. If you instruct us to do so, we will provide such other taxation, ad hoc and advisory services as may be agreed between us from time to time. These may be the subject of a separate engagement letter at our option. Where appropriate, we will agree with you a separate fee for any such work you instruct us to undertake. Examples of such work that you may wish to instruct us to undertake include:", "ind": 540, "flat": true}, {"k": "bullet", "t": "work in connection with workplace pension schemes other than that detailed above including helping with setting up and administering workplace pension schemes, including referring you to appropriate specialists where necessary;"}, {"k": "bullet", "t": "agreeing with you which employer-provided benefits-in-kind will be processed through the payroll and for which employees, processing through the payroll cash equivalent notional amounts on employee benefits-in-kind, notifying HMRC of in-year changes, advising you on the payment of associated Class 1A NIC, preparing and submitting return P11D(b) and notifications to employees;"}, {"k": "bullet", "t": "preparing and submitting returns P11D and P11D(b) for employee benefits-in-kind and expenses and advising on the payment of associated Class 1A NIC (such work, if undertaken, is covered in a separate schedule of services);"}, {"k": "bullet", "t": "dealing with any compliance check or enquiry by HMRC into the payroll data submitted and corresponding with HMRC as necessary;"}, {"k": "bullet", "t": "preparing and submitting any amended returns or data for previous tax years;"}, {"k": "bullet", "t": "assisting you in the operation of the Construction Industry Scheme (CIS) for subcontractors;"}, {"k": "bullet", "t": "conducting PAYE, and benefits and expenses health checks;"}, {"k": "bullet", "t": "helping you to allocate apprenticeship levy allowance across your different PAYE schemes/group companies/connected charities; and"}, {"k": "bullet", "t": "advising on ad hoc transactions, for example, termination payments to employees."}, {"k": "cont", "t": "If specialist advice is required, we may need to seek this from, or refer you to, appropriate specialists.", "ind": 540, "flat": true}, {"k": "snum", "t": "1.3\tChanges in the Law, in Practice or on Public Policy", "bold": true, "ind": 540}, {"k": "cont", "t": "We will not accept responsibility if you act on advice given by us on an earlier occasion without first confirming with us that the advice is still valid in the light of any change in the law, practice, public policy or in your circumstances.", "ind": 540, "flat": true}, {"k": "cont", "t": "We will accept no liability for losses arising from changes in the law (or the interpretation thereof), practice or public policy that are first published after the date on which the advice is given.", "ind": 540, "flat": true}, {"k": "shead", "t": "1.4\tYour Responsibilities", "ind": 540, "flat": true, "bold": true, "gapAfter": 1}, {"k": "cont", "t": "Even though you are engaging us to help you meet your payroll obligations, you are legally responsible for:", "ind": 540, "flat": true}, {"k": "bullet", "t": "ensuring that the data in your payroll submissions is correct and complete;"}, {"k": "bullet", "t": "complying with auto-enrolment obligations;"}, {"k": "bullet", "t": "making any submissions by the due date; and"}, {"k": "bullet", "t": "paying tax and NIC on time."}, {"k": "cont", "t": "Failure to do any of the above may lead to penalties and/or interest.", "ind": 540, "flat": true}, {"k": "cont", "t": "Employers cannot delegate these legal responsibilities to others.", "ind": 540, "flat": true}, {"k": "cont", "t": "You are no less responsible for errors in unapproved returns, submitted on the basis of the information provided to and processed by us, than if you had confirmed your approval of the returns.", "ind": 540, "flat": true}, {"k": "cont", "t": "We will communicate with {{pcTitle}} {{payrollContact}} in relation to the payroll services, having agreed with you that {{pcObj}} will represent {{entityShort}}.", "ind": 540, "flat": true}, {"k": "cont", "t": "To enable us to carry out our work, you agree:", "ind": 540, "flat": true}, {"k": "snum", "t": "a)\tthat all information required to be delivered online is submitted on the basis of full disclosure;", "ind": 990, "flat": true, "hangW": 450, "gapAfter": 0}, {"k": "snum", "t": "b)\tto provide full information necessary for dealing with your payroll affairs and workplace pension scheme contributions and refunds; we will rely on the information and documents being true, correct and complete and will not audit the information or those documents;", "ind": 990, "flat": true, "hangW": 450, "gapAfter": 0}, {"k": "snum", "t": "c)\tto agree with us the name(s) of the person(s) authorised by you to notify us of changes in employees and in rates of pay and other information relevant to the services provided under this schedule; we will process the changes only if notified by that/those individual(s);", "ind": 990, "flat": true, "hangW": 450, "gapAfter": 0}, {"k": "snum", "t": "d)\tto advise us in writing of changes of payroll pay dates;", "ind": 990, "flat": true, "hangW": 450, "gapAfter": 0}, {"k": "snum", "t": "e)\tto notify us at least 3 working days or such other period as agreed with us before the payroll pay date of all transactions or events which may need to be reflected in the payroll for the period, including details of:", "ind": 990, "flat": true, "hangW": 450, "gapAfter": 0}, {"k": "bullet2", "t": "all new employees (including full names, address, date of birth, gender, national insurance number, their start date and starter form) and details of their remuneration package including benefits-in-kind to be payrolled;", "ind": 1440, "hangW": 450}, {"k": "bullet2", "t": "for employees whose benefits-in-kind are being payrolled, their names, the identity of the benefits-in-kind, and the cash equivalent amounts to be included in payroll;", "ind": 1440, "hangW": 450}, {"k": "bullet2", "t": "for employees who are active pension scheme members, name of pension scheme, pensionable pay, employee and employer contribution rates, dates from/to which contributions and qualifying earnings payable;", "ind": 1440, "hangW": 450}, {"k": "bullet2", "t": "names and dates of birth of all apprentices aged under 25;", "ind": 1440, "hangW": 450}, {"k": "bullet2", "t": "names and dates of birth of all employees aged under 21;", "ind": 1440, "hangW": 450}, {"k": "bullet2", "t": "all changes to remuneration packages[including benefits-in-kind to be", "ind": 1440, "hangW": 450}, {"k": "bullet2", "t": "payrolled;", "ind": 1440, "hangW": 450}, {"k": "bullet2", "t": "employee expenses which need to be included in payroll to account for either income tax or Class 1 NIC or both;", "ind": 1440, "hangW": 450}, {"k": "bullet2", "t": "expenses for each employee if the expense is to be reimbursed gross through payroll as an addition to net pay;", "ind": 1440, "hangW": 450}, {"k": "bullet2", "t": "information necessary to enable us to calculate statutory payments, i.e., statutory sick pay, statutory maternity pay, statutory adoption pay, statutory paternity pay, statutory shared parental pay;", "ind": 1440, "hangW": 450}, {"k": "bullet2", "t": "irregular and/or ad hoc payments and the dates to be paid; and", "ind": 1440, "hangW": 450}, {"k": "bullet2", "t": "all leavers, their leaving date, termination payments, and any payments made after the leaving date.", "ind": 1440, "hangW": 450, "gapAfter": 0}, {"k": "snum", "t": "f)\tto notify us within 7 working days or such other period as agreed with us of your receiving or becoming aware of any opt-out notices or any other requests to cease membership of a scheme, so that we can cease to calculate any relevant pension contributions and process any required refunds;", "ind": 990, "flat": true, "hangW": 450, "gapAfter": 0}, {"k": "snum", "t": "g)\tto register with HMRC in advance of the tax year, to notify which benefits-in-kind are to be payrolled for which employees, and to notify in-year changes to HMRC (as agents, we cannot do this);", "ind": 990, "flat": true, "hangW": 450, "gapAfter": 0}, {"k": "snum", "t": "h)\tto keep us informed of changes in circumstances that could affect the payroll; if you are unsure whether a change is material, please tell us so we can assess its significance;", "ind": 990, "flat": true, "hangW": 450, "gapAfter": 0}, {"k": "snum", "t": "i)\tto authorise us to approach such third parties as may be appropriate, for information that we consider necessary to deal with your payroll; and", "ind": 990, "flat": true, "hangW": 450, "gapAfter": 0}, {"k": "snum", "t": "j)\tto approve:", "ind": 990, "flat": true, "hangW": 450, "gapAfter": 0}, {"k": "bullet2", "t": "in-year and final FPS by at least 3 working days before contractual pay dates so that they can be submitted on or before payday, or as agreed with us;", "ind": 1440, "gapAfter": 0, "hangW": 450}, {"k": "bullet2", "t": "in-year and final EPS by at least 3 days before the 19th of the month following the tax month;", "ind": 1440, "gapAfter": 0, "hangW": 450}, {"k": "bullet2", "t": "earlier year updates (EYU) within 3 days of notifying you of the data", "ind": 1440, "gapAfter": 0, "hangW": 450}, {"k": "bullet2", "t": "therein.", "ind": 1440, "gapAfter": 0, "hangW": 450}, {"k": "snum", "t": "k)\tto notify us within 7 working days or such other period as agreed with us in writing of your receiving any workplace pension scheme joining or opt-in notices, including the date you received the notice and the full names, addresses, gender, date of birth, national insurance number (NINO), unique email address and, if different from any standard rules agreed in accordance with the Checklist, their __pensionable pay__, the relevant employer and employee contribution rates, the relevant pension scheme, how tax relief is operated, i.e. relief at source or net pay; and whether their pension contributions will be made via salary sacrifice.", "ind": 990, "gapAfter": 1, "hangW": 450}, {"k": "cont", "t": "If the information required to complete the payroll services set out above is received later than the dates specified above or agreed with us, we will still endeavour to process the payroll and returns to meet the filing deadlines; but we will not be liable for any costs or other losses arising if the payroll is late or the returns are filed late in these circumstances. We may charge an additional fee £50+VAT for work carried out in a shorter time period.", "ind": 540, "flat": true}, {"k": "cont", "t": "If you require us to make a correction after the FPS or EPS has been submitted, you will let us know as soon as possible and, ideally, before the next payroll run. This will be subject to a separate fee.", "ind": 540, "flat": true}, {"k": "cont", "t": "HMRC will send you an agent authorisation code which expires within 30 days of issue. Please send this to us as soon as you receive it. This code will enable us to register as your agent with HM Revenue & Customs. This authorises HMRC to communicate with us as your agent, although they consider that you should still take 'reasonable care' over your tax affairs.", "ind": 540, "flat": true}, {"k": "cont", "t": "You will forward to us any communications received from HMRC, in sufficient time to enable us to deal with them as may be necessary within the requisite time limits. Although HMRC has the authority to communicate with us when form 64-8 has been submitted, it is essential that you let us have copies of any correspondence received, because HMRC are not obliged to send us copies of communications issued to you and, in most cases, will not do so. You should also keep a note of any telephone communication you have with HMRC's tax credits helpline, including the date and time of the call, and the name of the helpline operator(s).", "ind": 540, "flat": true}], "addendum": [{"k": "shead", "t": "ADDENDUM: DATA PROCESSOR AGREEMENT", "ind": 0}, {"k": "shead", "t": "1.\tIntroduction", "ind": 450}, {"k": "snum", "t": "1.1\tThis agreement relating to the processing of personal data (the “**Data Processor Agreement**”) regulates Luckmans Duckett Parker Limited (the “**Data Processor**”) processing of personal data on behalf of the client (the “**Data Controller**”) and is attached as an addendum to the Engagement Letter in which the parties have agreed the terms for the Data Processor’s delivery of services to the Data Controller.", "ind": 450}, {"k": "shead", "t": "2.\tLegislation", "ind": 450}, {"k": "snum", "t": "2.1\tThe Data Processor Agreement shall ensure that the Data Processor complies with the applicable data protection and privacy legislation (the “Applicable Law”), including in particular The **General Data Protection Regulation** (**GDPR**) (Regulation (EU) 2016/679)", "ind": 450}, {"k": "shead", "t": "3.\tProcessing of personal data", "ind": 450}, {"k": "snum", "t": "3.1\t**Purpose: **The purpose of the processing under the Engagement Letter is the provision of the Services by the Data Processor as specified in the Engagement Letter.", "ind": 450}, {"k": "snum", "t": "3.2\tIn connection with the Data Processor’s delivery of the Main Services to the Data Controller, the Data Processor will process certain categories and types of the Data Controller’s personal data on behalf of the Data Controller.", "ind": 450}, {"k": "snum", "t": "3.3\t”Personal data” includes “any information relating to an identified or identifiable natural person” as defined in GDPR, article 4 (1) (1) (the ”Personal Data”).  The categories and types of Personal Data processed by the Data Processor on behalf of the Data Controller are listed in sub-appendix A.  The Data Processor only performs processing activities that are necessary and relevant to perform the Main Services.  The parties shall update sub-appendix A whenever changes occur that necessitates an update.", "ind": 450}, {"k": "snum", "t": "3.4\tThe Data Processor shall have and maintain a register of processing activities in accordance with GDPR, article 32 (2).", "ind": 450}, {"k": "shead", "t": "4.\tInstruction", "ind": 450}, {"k": "snum", "t": "4.1\tThe Data Processor may only act and process the Personal Data in accordance with the documented instruction from the Data Controller (the ”Instruction”), unless required by law to act without such instruction.  The Instruction at the time of entering into this Data Processor Agreement (DPA) is that the Data Processor may only process the Personal Data with the purpose of delivering the Main Services as described in the Main Service Level Agreement.  Subject to the terms of this DPA and with mutual agreement of the parties, the Data Controller may issue additional written instructions consistent with the terms of this Agreement. The Data Controller is responsible for ensuring that all individuals who provide written instructions are authorised to do so.", "ind": 450}, {"k": "snum", "t": "4.2\tThe Data Controller guarantees to process Personal Data in accordance with the requirements of Data Protection Laws and Regulations.  The Data Controller’s instructions for the processing of Personal Data shall comply with Applicable Law. The Data Controller will have sole responsibility for the accuracy, quality, and legality of Personal Data and the means by which it was obtained.", "ind": 450}, {"k": "snum", "t": "4.3\tThe Data Processor will inform the Data Controller of any instruction that it deems to be in violation of Applicable Law and will not execute the instructions until they have been confirmed or modified.", "ind": 450}, {"k": "shead", "t": "5.\tThe Data Processor’s obligations", "ind": 450}, {"k": "snum", "t": "5.1\tConfidentiality", "ind": 450}, {"k": "snum", "t": "5.1.1\tThe Data Processor shall treat all the Personal Data as strictly confidential information.  The Personal Data may not be copied, transferred or otherwise processed in conflict with the Instruction, unless the Data Controller in writing has agreed.", "ind": 1080, "hangW": 630}, {"k": "snum", "t": "5.1.2\tThe Data Processor’s employees shall be subject to an obligation of confidentiality that ensures that the employees shall treat all the Personal Data under this DPA with strict confidentiality.", "ind": 1080, "hangW": 630}, {"k": "snum", "t": "5.1.3\tPersonal Data will only be made available to personnel that require access to such Personal Data for the delivery of the Main Services and this Data Processor Agreement.", "ind": 1080, "hangW": 630}, {"k": "snum", "t": "5.2\tThe Data Processor shall also ensure that employees processing the Personal Data only process the Personal Data in accordance with the Instruction.", "ind": 450}, {"k": "snum", "t": "5.3\tSecurity", "ind": 450}, {"k": "snum", "t": "5.3.1\tThe Data Processor shall implement the appropriate technical and organisational measures as set out in this Agreement and in the Applicable Law, including in accordance with GDPR, article 32.  The security measures are subject to technical progress and development.  The Data Processor may update or modify the security measures from time-to-time provided that such updates and modifications do not result in the degradation of the overall security.", "ind": 1080, "hangW": 630}, {"k": "snum", "t": "5.4\tThe Data Processor shall provide documentation for the Data Processor’s security measures if requested by the Data Controller in writing.", "ind": 450}, {"k": "snum", "t": "5.5\tData protection impact assessments and prior consultation", "ind": 450}, {"k": "snum", "t": "5.5.1\tIf the Data Processor’s assistance is necessary and relevant, the Data Processor shall assist the Data Controller in preparing data protection impact assessments in accordance with GDPR, article 35, along with any prior consultation in accordance with GDPR, article 36.", "ind": 1080, "hangW": 630}, {"k": "snum", "t": "5.6\tRights of the data subjects", "ind": 450}, {"k": "snum", "t": "5.6.1\tIf the Data Controller receives a request from a data subject for the exercise of the data subject’s rights under the Applicable Law and the correct and legitimate reply to such a request necessitates the Data Processor’s assistance, the Data Processor shall assist the Data Controller by providing the necessary information and documentation.  The Data Processor shall be given reasonable time to assist the Data Controller with such requests in accordance with the Applicable Law.", "ind": 1080, "hangW": 630}, {"k": "snum", "t": "5.6.2\tIf the Data Processor receives a request from a data subject for the exercise of the data subject’s rights under the Applicable Law and such request is related to the Personal Data of the Data Controller, the Data Processor must immediately forward the request to the Data Controller and must refrain from responding to the person directly.", "ind": 1080, "hangW": 630}, {"k": "snum", "t": "5.7\tPersonal Data Breaches", "ind": 450}, {"k": "snum", "t": "5.7.1\tThe Data Processor shall give immediate notice to the Data Controller if a breach occurs, that can lead to the accidental or unlawful destruction, loss, alteration, unauthorised disclosure of or access to, personal data transmitted, stored or otherwise processed re the Personal Data processed on behalf of the Data Controller (a “Personal Data Breach”).", "ind": 1080, "hangW": 630}, {"k": "snum", "t": "5.7.2\tThe Data Processor shall make reasonable efforts to identify the cause of such a breach and take those steps as they deem necessary to establish the cause, and to prevent such a breach from reoccurring.", "ind": 1080, "hangW": 630}, {"k": "snum", "t": "5.8\tDocumentation of compliance and Audit Rights", "ind": 450}, {"k": "snum", "t": "5.8.1\tUpon request by a Data Controller, the Data Processor shall make available to the Data Controller all relevant information necessary to demonstrate compliance with this DPA, and shall allow for and reasonably cooperate with audits, including inspections by the Data Controller or an auditor mandated by the Data Controller.  The Data Controller shall give notice of any audit or document inspection to be conducted and shall make reasonable endeavours to avoid causing damage or disruption to the Data Processors premises, equipment and business in the course of such an audit or inspection.  Any audit or document inspection shall be carried out with reasonable prior written notice of no less than 30 days, and shall not be conducted more than once a year.", "ind": 1080, "hangW": 630}, {"k": "snum", "t": "5.8.2\tThe Data Controller may be requested to sign a non-disclosure agreement reasonably acceptable to the Data Processor before being furnished with the above.", "ind": 1080, "hangW": 630}, {"k": "snum", "t": "5.9\tData Transfers", "ind": 450}, {"k": "snum", "t": "5.9.1\tOrdinarily, The Data Processor will not transfer your data to countries outside the European Economic Area.  In some cases, personal data will be saved on storage solutions that have servers outside the European Economic Area (EEA), for example, Dropbox or Google.  Only those storage solutions that provide secure services with adequate relevant safeguards will be employed.", "ind": 1080, "hangW": 630}, {"k": "shead", "t": "6.\tSub-Processors", "ind": 450}, {"k": "snum", "t": "6.1\tThe Data Processor is given general authorisation to engage third-parties to process the Personal Data (“Sub-Processors”) without obtaining any further written, specific authorisation from the Data Controller, provided that the Data Processor notifies the Data Controller in writing about the identity of a potential Sub-Processor (and its processors, if any) before any agreements are made with the relevant Sub-Processors and before the relevant Sub-Processor processes any of the Personal Data.  If the Data Controller wishes to object to the relevant Sub- Processor, the Data Controller shall give notice hereof in writing within ten (10) business days from receiving the notification from the Data Processor. Absence of any objections from the Data Controller shall be deemed a consent to the relevant Sub-Processor.", "ind": 450}, {"k": "snum", "t": "6.2\tIn the event the Data Controller objects to a new Sub-Processor and the Data Processor cannot accommodate the Data Controller’s objection, the Data Controller may terminate the Services by providing written notice to the Data Processor.", "ind": 450}, {"k": "snum", "t": "6.3\tThe Data Processor shall complete a written sub-processor agreement with any Sub-Processors.  Such an agreement shall at minimum provide the same data protection obligations as the ones applicable to the Data Processor, including the obligations under this Data Processor Agreement.  The Data Processor shall on an ongoing basis monitor and control its Sub- Processors’ compliance with the Applicable Law.  Documentation of such monitoring and control shall be provided to the Data Controller if so requested in writing.", "ind": 450}, {"k": "snum", "t": "6.4\tThe Data Processor is accountable to the Data Controller for any Sub-Processor in the same way as for its own actions and omissions.", "ind": 450}, {"k": "snum", "t": "6.5\tThe Data Processor is at the time of entering into this Data Processor Agreement using the Sub- Processors listed in sub-appendix B.  If the Data Processor initiates sub-processing with a new Sub-Processor, such new Sub-Processor shall be added to the list in sub-appendix B under paragraph 2.", "ind": 450}, {"k": "shead", "t": "7.\tRemuneration and Costs (Optional)", "ind": 450}, {"k": "snum", "t": "7.1\tThe Data Controller shall remunerate the Data Processor based on time spent to perform the obligations under section 5.5, 5.6, 5.7 and 5.8 of this Data Processor Agreement based on the Data Processor’s hourly rates.", "ind": 450}, {"k": "snum", "t": "7.2\tThe Data Processor is also entitled to remuneration for any time and material used to adapt and change the processing activities in order to comply with any changes to the Data Controller’s Instruction, including implementation costs and additional costs required to deliver the Main Services due to the change in the Instruction. The Data Processor is exempted from liability for non-performance with the Main Agreement if the performance of the obligations under the Main Agreement would be in conflict with any changed Instruction or if contractual delivery in accordance with the changed Instruction is impossible.  This could for instance be the case; (i) if the changes to the Instruction cannot technically, practically or legally be implemented; (ii) where the Data Controller explicitly requires that the changes to the Instruction shall be applicable before the changes can be implemented; and (iii) in the period of time until the Main Agreement is changed to reflect the new Instruction and commercial terms thereof.", "ind": 450}, {"k": "shead", "t": "8.\tLimitation of Liability", "ind": 450}, {"k": "snum", "t": "8.1\tThe total aggregate liability to the Client, of whatever nature, whether in contract, tort or otherwise, of the Data Processor for any losses whatsoever and howsoever caused arising from or in any way connected with this engagement shall be subject to the “Limitation of Liability” clause set out in the Main Service Level Agreement.", "ind": 450}, {"k": "snum", "t": "8.2\tNothing in this DPA will relieve the processor of its own direct responsibilities and liabilities under the GDPR.", "ind": 450}, {"k": "shead", "t": "9.\tDuration", "ind": 450}, {"k": "snum", "t": "9.1\tThe Data Processor Agreement shall remain in force until the Main Service Level Agreement is terminated.", "ind": 450}, {"k": "shead", "t": "10.\tData Protection Officer", "ind": 450}, {"k": "snum", "t": "10.1\tThe Data Processor will appoint a Data Protection Officer where such appointment is required by Data Protection Laws and Regulations.", "ind": 450}, {"k": "shead", "t": "11.\tTermination", "ind": 450}, {"k": "snum", "t": "11.1\tFollowing expiration or termination of the Agreement, the Data Processor will delete or return to the Data Controller all Personal Data in its possession as provided in the Agreement except to the extent the Data Processor is required by Applicable law to retain some or all of the Personal Data (in which case the Data Processor will archive the data and implement reasonable measures to prevent the Personal Data from any further processing).  The terms of this DPA will continue to apply to such Personal Data.", "ind": 450}, {"k": "shead", "t": "12.\tContact", "ind": 450}, {"k": "snum", "t": "12.1\tThe contact information for the Data Processor and the Data Controller is provided in the Main Service Level Agreement.", "ind": 450}, {"k": "shead", "t": "Agreement", "ind": 0, "break": true, "gapAfter": 4}, {"k": "cont", "t": "______________________________________________________________", "bold": true, "gapAfter": 0}, {"k": "cont", "t": "We agree to the terms of this Data Processor Agreement", "gapAfter": 4}, {"k": "cont", "t": "______________________________________\t________________", "rtab": true, "gapAfter": 0, "bold": true}, {"k": "cont", "t": "(On behalf of {{client}})\tDate", "rtab": true, "gapAfter": 3}, {"k": "signature", "t": "{{partner}}\t{{today}}", "rtab": true, "gapAfter": 0}, {"k": "cont", "t": "(On behalf of Luckmans Duckett Parker Limited)\tDate", "rtab": true}], "subappA": [{"k": "shead", "t": "Sub-Appendix A"}, {"k": "shead", "t": "1.\tPersonal Data", "ind": 450}, {"k": "snum", "t": "1.1\tThe Data Processor processes the following types of Personal Data in connection with the provision of the Main Services:", "ind": 450}, {"k": "bullet", "t": "Information on relevant employees from the Data Controller relevant for the processing of payroll and auto-enrolment"}, {"k": "bullet2", "t": "Name, postal address and email address"}, {"k": "bullet2", "t": "NI number"}, {"k": "bullet2", "t": "HMRC information"}, {"k": "bullet2", "t": "Bank account details"}, {"k": "bullet2", "t": "Pension details"}, {"k": "bullet2", "t": "Proof of identity"}, {"k": "bullet2", "t": "Leave records"}, {"k": "bullet2", "t": "Contract of employment & HR details"}, {"k": "bullet2", "t": "Next of kin details"}, {"k": "shead", "t": "2.\tCategories of data subjects", "ind": 450}, {"k": "snum", "t": "2.1\tThe Data Processor processes personal data about the following categories of data subjects:", "ind": 450}, {"k": "bullet", "t": "The Data Controller"}, {"k": "bullet", "t": "Employees of the Data Controller"}], "schedA": [{"k": "shead", "t": "SCHEDULE A", "gapAfter": 1}, {"k": "cont", "t": "This Schedule A includes certain details of the Processing of Customer Personal Data as required by Article 28(3) of the GDPR."}, {"k": "shead", "t": "1.\tSubject matter and duration of the processing of client personal data", "ind": 450}, {"k": "cont", "t": "The subject matter and duration of the processing of the client personal data are set out in the engagement letter between us dated {{today}}.", "ind": 450, "flat": true}, {"k": "shead", "t": "2.\tThe nature and purpose of the processing of client personal data", "ind": 450}, {"k": "tabitem", "t": "Company secretarial records", "ind": 450}, {"k": "tabitem", "t": "Processing of payroll and auto-enrolment information", "ind": 450}, {"k": "shead", "t": "3.\tThe types of client personal data to be processed", "ind": 450}, {"k": "tabitem", "t": "Personal Data", "ind": 450}, {"k": "tabitem", "t": "Name, postal address and e-mail address", "ind": 450}, {"k": "tabitem", "t": "National Insurance Number", "ind": 450}, {"k": "tabitem", "t": "Date of Birth", "ind": 450}, {"k": "tabitem", "t": "Bank account details", "ind": 450}, {"k": "tabitem", "t": "Pension details", "ind": 450}, {"k": "tabitem", "t": "Sick pay, maternity or paternity records", "ind": 450}, {"k": "tabitem", "t": "Other HMRC information", "ind": 450}, {"k": "shead", "t": "4.\tThe categories of data subject to whom the client personal data relates", "ind": 450}, {"k": "tabitem", "t": "Employees of the client", "ind": 450}, {"k": "tabitem", "t": "Directors of the client", "ind": 450}, {"k": "tabitem", "t": "Shareholders of the client", "ind": 450}, {"k": "tabitem", "t": "Persons of Significant Control", "ind": 450}, {"k": "shead", "t": "5.\tYour obligations and rights", "ind": 450}, {"k": "cont", "t": "Your obligations and rights are set out in the engagement letter between us dated {{today}}.", "ind": 450, "flat": true}], "schedB": [{"k": "shead", "t": "SCHEDULE B", "gapAfter": 1}, {"k": "cont", "t": "This Schedule B includes a list of our sub-processors."}, {"k": "shead", "t": "1.\tApproved Sub-Processors", "ind": 450}, {"k": "cont", "t": "The following sub-processors shall be considered approved by the Data Controller at the time of entering into this agreement:", "ind": 450, "flat": true}, {"k": "cont", "t": "LDPJ Associates LLP, 807, D Mall, Netaji Subhash Place, Pitampura, New Delhi", "ind": 450, "flat": true}, {"k": "cont", "t": "IDM3 Limited, 1110 Elliott Court, Coventry Business Park, Herald Avenue, Coventry, CV5 6UB", "ind": 450, "flat": true}, {"k": "cont", "t": "Cook Accountancy Services Limited, 1110 Elliott Court, Coventry Business Park, Herald Avenue, Coventry, CV5 6UB", "ind": 450, "flat": true}, {"k": "cont", "t": "Les Praz Consulting Limited, 1110 Elliott Court, Coventry Business Park, Herald Avenue, Coventry, CV5 6UB", "ind": 450, "flat": true}]}, "cover": [{"id": "ref", "k": "plain", "when": "", "t": "Our Ref: {{ref}}"}, {"id": "date", "k": "plain", "when": "", "t": "{{today}}"}, {"id": "gap1", "k": "spacer", "when": "", "t": ""}, {"id": "addressee", "k": "addr", "when": "addressee", "t": "{{addressee}}"}, {"id": "clientline", "k": "addr", "when": "", "t": "{{client}}"}, {"id": "address", "k": "addrblock", "when": "", "t": "{{address}}"}, {"id": "dear", "k": "plain", "when": "", "t": "Dear {{dear}}"}, {"id": "intro", "k": "plain", "when": "", "t": "The purpose of this letter, along with the attached {{SCHED}} of professional services and related terms of business, is to set out the basis on which we are to act as {{acting}} of {{ofClient}} and the respective areas of responsibilit{{respPl}} of {{resp}} and of ourselves."}, {"id": "intro2", "k": "plain", "when": "isIndividual", "t": "To enable us to perform these services we will require you to provide us with all relevant information."}, {"id": "s1", "k": "clause", "when": "", "t": "Professional Services Provided"}, {"id": "s1p1", "k": "para", "when": "", "t": "The professional services you have asked us to carry out are as follows:-"}, {"id": "s1list", "k": "servicelist", "when": "", "t": ""}, {"id": "s1p2", "k": "para", "when": "", "t": "The scope of these services is set out in the attached {{SCHED}} of professional services and should be read in conjunction with our most recent terms of business at appendix 2 dated {{tobVersion}}. Only the services which are listed in the attached {{SCHED}} are included within the scope of our instructions. If there is additional work that you wish us to carry out which is not listed in the {{SCHED}}, please let us know and we will discuss with you whether they can be included in the scope of our work. Any additional services that you ask us to provide will be subject to new or amended terms of engagement."}, {"id": "s2", "k": "clause", "when": "", "t": "Agreement of Terms"}, {"id": "s2p1a", "k": "para", "when": "payrollOnly", "t": "The terms set out in this letter, which includes the {{SCHED}} of professional services and terms of business, shall take effect immediately upon your countersigning this letter and returning it to us."}, {"id": "s2p1b", "k": "para", "when": "!payrollOnly", "t": "The terms set out in this letter, which includes the {{SCHED}} of professional services and terms of business, shall take effect immediately upon your countersigning this letter and returning it to us or upon the commencement of the work for the {{period}} {{periodEnd}} whichever is the earlier."}, {"id": "s2p2a", "k": "para", "when": "prevNamed", "t": "We will not be responsible for earlier periods. Your previous Advisers, {{prevAdviser}}, will deal with the accounts and outstanding returns, assessments and other matters relating to earlier periods and will agree the position with the relevant authorities."}, {"id": "s2p2b", "k": "para", "when": "prevUnnamed", "t": "We will not be responsible for earlier periods. Your previous Advisers will deal with the accounts and outstanding returns, assessments and other matters relating to earlier periods and will agree the position with the relevant authorities."}, {"id": "s2p3a", "k": "para", "when": "isIndividual", "t": "Once it has been agreed, this letter will remain effective, from one appointment to another, until it is replaced. We shall be grateful if you could confirm in writing your agreement to these terms by signing and returning the enclosed copy of this letter or let us know if they are not in accordance with your understanding of our terms of engagement."}, {"id": "s2p3b", "k": "para", "when": "!isIndividual", "t": "Once it has been agreed, this letter will remain effective until it is replaced. We shall be grateful if you could confirm in writing your agreement to these terms by signing and returning the enclosed copy of this letter or let us know if they are not in accordance with your understanding of our terms of engagement."}, {"id": "s2p4", "k": "para", "when": "", "t": "Data Protection - we are committed to ensuring the protection of the privacy and security of any personal data which we process. Your attention is drawn to {{xref:dp}} of the attached terms of business which details how we treat personal data received by us in the provision of our services during our engagement with you. By signing this letter, you confirm that you have read and understood {{xref:dp}} and any privacy notice referred to therein."}, {"id": "s3", "k": "clause", "when": "", "t": "Fees"}, {"id": "s3p1", "k": "para", "when": "", "t": "Our fees will be charged in accordance with our attached standard terms and conditions. Please review these to ensure you understand the basis of our charges and our payment terms."}, {"id": "s4", "k": "clause", "when": "", "t": "Limitation of Liability"}, {"id": "s4p1", "k": "para", "when": "", "t": "We specifically draw your attention to {{xref:liab}} of our standard terms and conditions which sets out the basis on which we limit our liability to you and to others. You should read this in conjunction with {{xref:tp}} of our standard terms and conditions which excludes liability to third parties."}, {"id": "s4p2", "k": "para", "when": "", "t": "No Third Parties should be entitled to rely on the work done pursuant to this engagement letter."}, {"id": "s4p3", "k": "para", "when": "", "t": "Our aggregate liability to you and any third parties who we have agreed may rely on our work and whether in contract or otherwise of this firm, its partners, directors, employees and agents for any losses in any way connected with any of the services provided to you under the terms of this Letter of Engagement (and including interest) shall not exceed the sum of £{{cap}}, which we regard as fair and reasonable in the circumstances of this assignment. In agreeing this figure with you, we have taken into account the nature of the Engagement, the availability to us of insurance cover and other options available to you."}, {"id": "s4p4", "k": "para", "when": "", "t": "We would advise you to take independent advice before signing this Engagement Letter since, by doing so, you will agree to its terms including the limitations on our liability."}, {"id": "s5", "k": "clause", "when": "", "t": "{{np}}"}, {"id": "s5p1", "k": "para", "when": "", "t": "For the avoidance of doubt {{npTitle}} {{nominated}} {{npHas}} agreed to act and {{npIs}} acting as the {{np}}."}, {"id": "s5p2", "k": "para", "when": "", "t": "By signing this Engagement Letter you confirm and warrant that the {{np}} set out above {{npIs}} authorised to give instructions and information to us on your behalf and to receive our advice and work product on behalf of you."}, {"id": "s5p3", "k": "para", "when": "", "t": "Any change to the {{np}} should be notified to us in writing and will not be effective until acknowledged by us in writing."}, {"id": "yf", "k": "plain", "when": "", "t": "Yours faithfully"}, {"id": "gapsig", "k": "spacer", "when": "", "t": ""}, {"id": "sigimage", "k": "signature", "when": "", "t": "{{partner}}"}, {"id": "sigpartner", "k": "plain", "when": "", "t": "{{partnerCaps}}", "nogap": true}, {"id": "obo1", "k": "plain", "when": "", "t": "Signed for and on behalf of", "nogap": true}, {"id": "obo2", "k": "plain", "when": "", "t": "LUCKMANS DUCKETT PARKER LIMITED"}, {"id": "accept", "k": "plain", "when": "", "t": "{{agree}} agree to the terms of this letter, together with the attached {{SCHED}} of professional services and Terms of Business by signing and returning one copy of this letter. If this letter is not returned to us (signed or amended), no comment is made to us in writing within 15 working days of the date of this letter, then terms will, for legal purposes, be deemed to have been accepted.", "break": true}, {"id": "sigblocks", "k": "sigblocks", "when": "", "t": "", "gapBefore": 3}, {"id": "counter1", "k": "plain", "when": "counterSign", "t": "Name\t{{sig1}} \t\tSigned………………………………………"}, {"id": "counter2", "k": "plain", "when": "counterSign", "t": "Date……………………..\tas an individual in relation to Appendix 2", "ind": 3600}], "letterhead": {"logo": "", "logoWidthMm": 22, "colWidthMm": 40, "topMm": 14, "rightMm": 9, "strapline": ["Chartered Accountants", "Business & Taxation", "Advisors"], "groups": [{"h": "Directors", "names": [["Ash Rishiraj", "FCA"], ["Mark Spafford", "FCA  FCCA"], ["Nick Waterhouse-Brown", "FCA  CTA"], ["Karl Goddard", "FCCA  CTA"]]}, {"h": "Senior Associates", "names": [["Rich Farr", "FCCA"]]}, {"h": "Consultants", "names": [["Steve Twigger", "FCA  FCCA"], ["Terry Frankton", "FCA"], ["Graham Parker", "FCA"]]}], "office": {"h": "Coventry Office", "lines": ["1110 Elliott Court", "Coventry Business Park", "Herald Avenue", "Coventry", "CV5 6UB"], "contact": ["024 7662 7200", "024 7667 6705", "partners@luckmans.com", "luckmans.com"]}, "badge": "", "badgeWidthMm": 28, "footer": ["Registered to carry on audit work in the UK and regulated for a range of investment business activities by the Institute of Chartered Accountants in England and Wales.", "LDP Luckmans and Catalyst Business Support are the trading names of Luckmans Duckett Parker Limited. Registered in England and Wales. Company No. 7146825", "Registered office: 1110 Elliott Court, Coventry Business Park, Herald Avenue, Coventry, CV5 6UB"]}, "type": {"bodyPt": 10, "termsPt": 9, "labelPt": 8.5, "lhPt": 6.8, "footPt": 5.8}};
