/* ---------------- read an existing .docx and swap only its body ----------------
   Everything of yours is kept: header, footer, logo, styles, page setup,
   numbering definitions. Only the body paragraphs are replaced. -------------- */
async function readZip(buf) {
  const u = new Uint8Array(buf), dv = new DataView(buf);
  let eo = -1;
  for (let i = u.length - 22; i >= 0 && i > u.length - 66000; i--)
    if (dv.getUint32(i, true) === 0x06054b50) { eo = i; break; }
  if (eo < 0) throw new Error("Not a zip file");
  const n = dv.getUint16(eo + 10, true); let p = dv.getUint32(eo + 16, true);
  const out = [];
  for (let k = 0; k < n; k++) {
    const nameLen = dv.getUint16(p + 28, true), extLen = dv.getUint16(p + 30, true),
      cmtLen = dv.getUint16(p + 32, true), method = dv.getUint16(p + 10, true),
      csize = dv.getUint32(p + 20, true), lho = dv.getUint32(p + 42, true);
    const name = new TextDecoder().decode(u.subarray(p + 46, p + 46 + nameLen));
    const lnLen = dv.getUint16(lho + 26, true), leLen = dv.getUint16(lho + 28, true);
    const start = lho + 30 + lnLen + leLen;
    let data = u.subarray(start, start + csize);
    if (method === 8) {
      const ds = new DecompressionStream("deflate-raw");
      const ab = await new Response(new Blob([data]).stream().pipeThrough(ds)).arrayBuffer();
      data = new Uint8Array(ab);
    }
    out.push({ name, data });
    p += 46 + nameLen + extLen + cmtLen;
  }
  return out;
}



