/* Word stores the logo as a small mark inside a large, mostly empty canvas.
   Used as-is it renders as a big blank box that collides with the text below,
   so trim the transparent or white border before using it. */
function trimImage(dataUrl) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      try {
        const w = img.naturalWidth, h = img.naturalHeight;
        const cv = document.createElement("canvas");
        cv.width = w; cv.height = h;
        const cx = cv.getContext("2d");
        cx.drawImage(img, 0, 0);
        const d = cx.getImageData(0, 0, w, h).data;
        let x0 = w, y0 = h, x1 = -1, y1 = -1;
        for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
          const i = (y * w + x) * 4;
          const a = d[i + 3];
          const light = d[i] > 244 && d[i + 1] > 244 && d[i + 2] > 244;
          if (a > 12 && !light) {
            if (x < x0) x0 = x; if (x > x1) x1 = x;
            if (y < y0) y0 = y; if (y > y1) y1 = y;
          }
        }
        if (x1 < 0 || (x1 - x0) < 8 || (y1 - y0) < 8) return resolve(dataUrl);
        const pad = 2;
        x0 = Math.max(0, x0 - pad); y0 = Math.max(0, y0 - pad);
        x1 = Math.min(w - 1, x1 + pad); y1 = Math.min(h - 1, y1 + pad);
        const cw = x1 - x0 + 1, ch = y1 - y0 + 1;
        const o = document.createElement("canvas");
        const scale = Math.min(1, 560 / Math.max(cw, ch));
        o.width = Math.round(cw * scale); o.height = Math.round(ch * scale);
        o.getContext("2d").drawImage(img, x0, y0, cw, ch, 0, 0, o.width, o.height);
        resolve(o.toDataURL("image/png"));
      } catch (e) { resolve(dataUrl); }
    };
    img.onerror = () => resolve(dataUrl);
    img.src = dataUrl;
  });
}

async function harvestLetterhead(entries) {
  const dec = new TextDecoder();
  const ent = (t) => t.replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&#x?\w+;/g, "");
  const clean = (t) => ent(t).replace(/[\uF000-\uF0FF\u2022`]/g, "")
    .replace(/^@(?![\w.])/, "").replace(/\s+/g, " ").trim();
  const HEADS = /^(Directors?|Senior Associates?|Associates?|Consultants?|Partners?)$/i;
  const out = {};

  const toDataUrl = (e) => {
    let bin = ""; const u = e.data;
    for (let i = 0; i < u.length; i += 8192) bin += String.fromCharCode.apply(null, u.subarray(i, i + 8192));
    const mime = /\.jpe?g$/i.test(e.name) ? "image/jpeg" : /\.gif$/i.test(e.name) ? "image/gif" : "image/png";
    return "data:" + mime + ";base64," + btoa(bin);
  };
  const media = entries.filter((e) => /^word\/media\//.test(e.name));
  if (media.length) {
    const big = media.slice().sort((a, b) => b.data.length - a.data.length)[0];
    if (big) out.logo = await trimImage(toDataUrl(big));
    const small = media.filter((e) => e !== big && e.data.length > 3000 && e.data.length < 40000)
      .sort((a, b) => b.data.length - a.data.length)[0];
    if (small) out.badge = await trimImage(toDataUrl(small));
  }

  const paraText = (xml) => (xml.match(/<w:p\b[\s\S]*?<\/w:p>/g) || []).map((par) => {
    const runs = (par.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || []).map((x) => x.replace(/<[^>]+>/g, ""));
    return runs.join("");
  });

  for (const h of entries.filter((e) => /^word\/header\d*\.xml$/.test(e.name))
      .sort((a, b) => b.data.length - a.data.length)) {
    /* split any paragraph that glued a heading onto the first name, e.g. "DirectorsAsh Rishiraj" */
    let lines = [];
    for (const raw of paraText(dec.decode(h.data))) {
      const t = clean(raw);
      if (!t) continue;
      const m = t.match(/^(Directors|Senior Associates|Consultants|Partners|Associates)(?=[A-Z])(.*)$/);
      if (m) { lines.push(m[1]); if (clean(m[2])) lines.push(clean(m[2])); } else lines.push(t);
    }
    if (lines.length < 4) continue;

    /* the header repeats its whole content, so cut where the first line recurs.
       Deduping every line would cut at a repeated qualification such as FCA FCCA. */
    const again = lines.indexOf(lines[0], 1);
    if (again > 3) lines = lines.slice(0, again);

    const strap = [], groups = [], office = { h: "", lines: [], contact: [] };
    let mode = "strap", g = null;
    for (const t of lines) {
      if (/office$/i.test(t) && t.length < 34) { mode = "office"; office.h = t; continue; }
      if (mode !== "office" && HEADS.test(t)) { g = { h: t, names: [] }; groups.push(g); mode = "names"; continue; }
      if (mode === "strap") { strap.push(t); continue; }
      if (mode === "names" && g) {
        if (/^[A-Z]{2,}(\s+[A-Z]{2,})*$/.test(t) && g.names.length) g.names[g.names.length - 1][1] = t;
        else g.names.push([t, ""]);
        continue;
      }
      if (mode === "office") {
        if (/@|www|\.com|^[\d\s]{7,}$/i.test(t)) office.contact.push(t); else office.lines.push(t);
      }
    }
    if (strap.length) out.strapline = strap.slice(0, 4);
    if (groups.length) out.groups = groups.filter((x) => x.names.length);
    if (office.lines.length || office.contact.length) out.office = office;
    break;
  }

  for (const ftr of entries.filter((e) => /^word\/footer\d*\.xml$/.test(e.name))
      .sort((a, b) => b.data.length - a.data.length)) {
    let paras = paraText(dec.decode(ftr.data)).map(clean).filter((t) => t.length > 25);
    const rep = paras.indexOf(paras[0], 1);
    if (rep > 0) paras = paras.slice(0, rep);
    if (paras.length) { out.footer = paras; break; }
  }
  return out;
}

function mergeIntoTemplate(entries, bodyXml, numAdditions) {
  const dec = new TextDecoder(), enc2 = (s) => new TextEncoder().encode(s);
  return entries.map((e) => {
    if (e.name === "word/document.xml") {
      const xml = dec.decode(e.data);
      const open = xml.indexOf("<w:body>");
      const close = xml.lastIndexOf("</w:body>");
      if (open < 0 || close < 0) return e;
      const inner = xml.slice(open + 8, close);
      const sect = (inner.match(/<w:sectPr[\s\S]*<\/w:sectPr>/) || [""])[0];   // keep your page setup and header links
      return { name: e.name, data: enc2(xml.slice(0, open + 8) + bodyXml + sect + xml.slice(close)) };
    }
    if (e.name === "word/numbering.xml" && numAdditions) {
      const xml = dec.decode(e.data);
      const i = xml.lastIndexOf("</w:numbering>");
      if (i < 0) return e;
      return { name: e.name, data: enc2(xml.slice(0, i) + numAdditions + xml.slice(i)) };
    }
    return e;
  });
}

