/* ---------------- date parsing and picker ---------------- */
const MONTHS = ["January","February","March","April","May","June","July","August","September","October","November","December"];
const ord = (d) => d + (d % 10 === 1 && d !== 11 ? "st" : d % 10 === 2 && d !== 12 ? "nd" : d % 10 === 3 && d !== 13 ? "rd" : "th");
const fmtDate = (dt) => ord(dt.getDate()) + " " + MONTHS[dt.getMonth()] + " " + dt.getFullYear();
const monthFrom = (tok) => {
  const t = tok.toLowerCase().replace(/\./g, "");
  const i = MONTHS.findIndex((m) => m.toLowerCase() === t || m.toLowerCase().slice(0, 3) === t.slice(0, 3) && t.length >= 3);
  return i;
};
function parseDate(raw) {
  if (!raw) return null;
  let s = String(raw).trim().toLowerCase()
    .replace(/(\d)(st|nd|rd|th)\b/g, "$1")
    .replace(/,/g, " ")
    .replace(/\s+/g, " ");
  const yr = (y) => { y = +y; return y < 100 ? (y > 50 ? 1900 + y : 2000 + y) : y; };
  const mk = (d, m, y) => { d = +d; m = +m; y = yr(y);
    if (!(m >= 1 && m <= 12) || !(d >= 1 && d <= 31)) return null;
    const dt = new Date(y, m - 1, d);
    return dt.getMonth() === m - 1 && dt.getDate() === d ? dt : null; };
  let m;
  /* a written month anywhere: 1 aug 2026 / aug 1 2026 / 1 august 26 */
  const parts = s.split(/[\s\/\-\.]+/).filter(Boolean);
  if (parts.length === 3) {
    const mi = parts.findIndex((p) => /[a-z]/.test(p));
    if (mi >= 0) {
      const mo = monthFrom(parts[mi]);
      if (mo >= 0) {
        const rest = parts.filter((_, i) => i !== mi);
        const [a, b] = rest;
        const day = a.length === 4 ? b : a, y = a.length === 4 ? a : b;
        const r = mk(day, mo + 1, y); if (r) return r;
      }
    }
  }
  if (parts.length === 2) {
    const mi = parts.findIndex((p) => /[a-z]/.test(p));
    if (mi >= 0) { const mo = monthFrom(parts[mi]);
      if (mo >= 0) { const other = parts[1 - mi];
        const r = other.length === 4 ? mk(1, mo + 1, other) : mk(other, mo + 1, new Date().getFullYear());
        if (r) return r; } }
  }
  /* iso with separators: 2026-08-01 */
  if ((m = s.match(/^(\d{4})[\/\-\.](\d{1,2})[\/\-\.](\d{1,2})$/))) { const r = mk(m[3], m[2], m[1]); if (r) return r; }
  /* day first: 1/8/2026, 1-8-26, 1.8.2026 */
  if ((m = s.match(/^(\d{1,2})[\/\-\. ](\d{1,2})[\/\-\. ](\d{2,4})$/))) { const r = mk(m[1], m[2], m[3]); if (r) return r; }
  /* no separators: 8 digits are ddmmyyyy, falling back to yyyymmdd */
  if ((m = s.match(/^(\d{8})$/))) { const d8 = m[1];
    let r = mk(d8.slice(0, 2), d8.slice(2, 4), d8.slice(4)); if (r) return r;
    r = mk(d8.slice(6), d8.slice(4, 6), d8.slice(0, 4)); if (r) return r; }
  /* 6 digits are ddmmyy */
  if ((m = s.match(/^(\d{6})$/))) { const r = mk(m[1].slice(0, 2), m[1].slice(2, 4), m[1].slice(4)); if (r) return r; }
  /* day and month only: 1/8 */
  if ((m = s.match(/^(\d{1,2})[\/\-\. ](\d{1,2})$/))) { const r = mk(m[1], m[2], new Date().getFullYear()); if (r) return r; }
  const t = Date.parse(s); if (!isNaN(t)) return new Date(t);
  return null;
}

function DateField({ value, onChange, style, mono, align }) {
  const [raw, setRaw] = React.useState(null);
  const [open, setOpen] = React.useState(false);
  const parsed = parseDate(raw === null ? value : raw);
  const base = parseDate(value) || new Date();
  const [view, setView] = React.useState({ y: base.getFullYear(), m: base.getMonth() });
  const commit = () => { if (parsed) onChange(fmtDate(parsed)); setRaw(null); };
  const first = new Date(view.y, view.m, 1);
  const lead = (first.getDay() + 6) % 7;
  const days = new Date(view.y, view.m + 1, 0).getDate();
  const cur = parseDate(value);
  const cell = { fontFamily: UI, fontSize: 11, padding: "3px 0", borderRadius: 2, textAlign: "center", cursor: "pointer" };
  return (
    <div style={{ position: "relative" }}>
      <div style={{ display: "flex", gap: 4 }}>
        <input value={raw === null ? (value || "") : raw}
          onChange={(e) => setRaw(e.target.value)}
          onBlur={commit}
          onKeyDown={(e) => { if (e.key === "Enter") { commit(); e.target.blur(); } }}
          placeholder="1/8/26 or 1 aug 2026"
          style={{ ...style, fontFamily: mono ? MONO : UI }} />
        <button onClick={() => { const b = parseDate(value) || new Date(); setView({ y: b.getFullYear(), m: b.getMonth() }); setOpen(!open); }}
          style={{ border: `1px solid ${C.rule}`, borderRadius: 3, padding: "0 6px", background: "#fff", color: C.muted }}
          title="Calendar"><CalendarIcon size={13} /></button>
      </div>
      {raw !== null && raw !== "" && (
        <div style={{ fontFamily: UI, fontSize: 10, marginTop: 2, color: parsed ? C.accent : C.ochre }}>
          {parsed ? fmtDate(parsed) : "not recognised"}
        </div>)}
      {open && (
        <div style={{ position: "absolute", zIndex: 40, top: "100%", [align === "left" ? "left" : "right"]: 0, marginTop: 4, background: "#fff",
          border: `1px solid ${C.rule}`, borderRadius: 4, boxShadow: "0 6px 20px rgba(20,32,31,.16)", padding: 8, width: 210 }}>
          <div className="flex items-center justify-between mb-1">
            <button onClick={() => setView(view.m ? { ...view, m: view.m - 1 } : { y: view.y - 1, m: 11 })} style={{ color: C.muted, padding: "0 4px" }}>‹</button>
            <select value={view.m} onChange={(e) => setView({ ...view, m: +e.target.value })} style={{ fontFamily: UI, fontSize: 11.5, border: "none", background: "transparent", fontWeight: 600, color: C.ink }}>
              {MONTHS.map((mm, i) => <option key={i} value={i}>{mm}</option>)}</select>
            <input value={view.y} onChange={(e) => setView({ ...view, y: +e.target.value || view.y })} style={{ width: 44, fontFamily: UI, fontSize: 11.5, border: "none", fontWeight: 600, color: C.ink, textAlign: "center" }} />
            <button onClick={() => setView(view.m < 11 ? { ...view, m: view.m + 1 } : { y: view.y + 1, m: 0 })} style={{ color: C.muted, padding: "0 4px" }}>›</button>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(7,1fr)", gap: 1 }}>
            {["M", "T", "W", "T", "F", "S", "S"].map((d, i) => <div key={i} style={{ ...cell, color: C.muted, fontWeight: 700, cursor: "default" }}>{d}</div>)}
            {Array.from({ length: lead }).map((_, i) => <div key={"b" + i} />)}
            {Array.from({ length: days }).map((_, i) => {
              const d = i + 1;
              const isCur = cur && cur.getFullYear() === view.y && cur.getMonth() === view.m && cur.getDate() === d;
              return <div key={d} onClick={() => { onChange(fmtDate(new Date(view.y, view.m, d))); setRaw(null); setOpen(false); }}
                style={{ ...cell, background: isCur ? C.accent : "transparent", color: isCur ? "#fff" : C.ink, fontWeight: isCur ? 700 : 400 }}>{d}</div>;
            })}
          </div>
          <div className="flex justify-between mt-1.5">
            <button onClick={() => { onChange(fmtDate(new Date())); setRaw(null); setOpen(false); }} style={{ fontFamily: UI, fontSize: 11, color: C.accent, fontWeight: 600 }}>Today</button>
            <button onClick={() => setOpen(false)} style={{ fontFamily: UI, fontSize: 11, color: C.muted }}>Close</button>
          </div>
        </div>)}
    </div>);
}


const INP = { fontFamily: UI, fontSize: 12.5, lineHeight: 1.4, color: C.ink, background: C.surf, border: `1px solid ${C.rule}`, borderRadius: 8, padding: "6px 9px", minHeight: 32, width: "100%", minWidth: 0, boxSizing: "border-box" };
